import * as THREE from 'three';
import type { CafeItemId } from '../gameplay/cafeData';
import { createDrink, type DrinkModel } from '../render/drinks';

/**
 * A small isolated renderer for the rotating drink beside the popup menu.
 * It owns its own scene so the menu does not disturb the town camera.
 */
export class MenuPreview {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(30, 1, 0.01, 10);
  private model: DrinkModel | null = null;
  private active = false;
  private shownId: CafeItemId | null = null;
  private lastWidth = 0;
  private lastHeight = 0;

  constructor(private readonly canvas: HTMLCanvasElement) {
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'low-power',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;

    this.camera.position.set(0, 0.36, 0.6);
    this.camera.lookAt(0, 0.12, 0);

    const hemi = new THREE.HemisphereLight(0xfff4e2, 0x29322b, 2.1);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xffe8c8, 3.4);
    key.position.set(1.4, 2.2, 1.6);
    this.scene.add(key);

    const fill = new THREE.DirectionalLight(0xbdd6c6, 1.5);
    fill.position.set(-1.6, 1.0, -0.8);
    this.scene.add(fill);

    const rim = new THREE.DirectionalLight(0xfff0d2, 1.2);
    rim.position.set(-0.4, 1.4, -2.0);
    this.scene.add(rim);
  }

  get itemId(): CafeItemId | null {
    return this.shownId;
  }

  setActive(active: boolean): void {
    this.active = active;
  }

  show(id: CafeItemId): void {
    if (this.shownId === id && this.model) {
      this.active = true;
      this.resize();
      return;
    }
    this.model?.dispose();
    this.model = createDrink(id);
    this.shownId = id;
    this.scene.add(this.model.group);
    this.active = true;
    this.resize();
  }

  update(dt: number): void {
    if (!this.active || !this.model) return;
    // The popup is hidden on first show, so the canvas has no client size
    // until the browser has laid it out. Pick it up on the next frame.
    if (this.canvas.clientWidth !== this.lastWidth || this.canvas.clientHeight !== this.lastHeight) {
      this.resize();
    }
    // A slow, steady turn; the small bob keeps the silhouette from feeling
    // like a turntable render.
    this.model.group.rotation.y += dt * 0.85;
    this.model.group.position.y = Math.sin(performance.now() * 0.0012) * 0.003;
    this.renderer.render(this.scene, this.camera);
  }

  resize(): void {
    const width = this.canvas.clientWidth || 280;
    const height = this.canvas.clientHeight || 280;
    this.lastWidth = width;
    this.lastHeight = height;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  dispose(): void {
    this.model?.dispose();
    this.model = null;
    this.renderer.dispose();
  }
}
