import * as THREE from 'three';
import { createCurvedDepthMaterial, type CurveUniforms } from './curved';
import { clamp } from '../core/math';

/**
 * One wind state shared by foliage, sea ripples, and the foam lines. Keeping a
 * single direction and strength means a gust visibly pushes the palm fronds and
 * the waves the same way instead of each effect drifting on its own clock.
 *
 * The breeze is onshore: it blows from the sea toward the town, so foam rolls
 * up the beach while the leaves lean inland.
 */
export interface WindUniforms {
  time: { value: number };
  direction: { value: THREE.Vector2 };
  strength: { value: number };
}

const BASE_ANGLE = 1.18;
const windUniforms: WindUniforms = {
  time: { value: 0 },
  direction: { value: new THREE.Vector2(Math.cos(BASE_ANGLE), Math.sin(BASE_ANGLE)) },
  strength: { value: 0.85 },
};

const WIND_MATERIALS = new Set([
  'MAT_Foliage',
  'MAT_Foliage_Dark',
  'MAT_Palm_Leaf',
  'MAT_Palm_Leaf_Dark',
]);

export interface WindSample {
  time: number;
  x: number;
  z: number;
  strength: number;
}

export function getWind(): WindSample {
  return {
    time: windUniforms.time.value,
    x: windUniforms.direction.value.x,
    z: windUniforms.direction.value.y,
    strength: windUniforms.strength.value,
  };
}

/**
 * Advance the breeze with real seconds. The direction turns slowly enough to
 * read as weather, while strength rises and falls in overlapping gusts.
 */
export function advanceWind(dt: number): void {
  const time = windUniforms.time.value + dt;
  const angle =
    BASE_ANGLE +
    Math.sin(time * 0.035 + 0.7) * 0.18 +
    Math.sin(time * 0.011) * 0.09;
  const strength = clamp(
    0.82 + Math.sin(time * 0.27) * 0.14 + Math.sin(time * 0.67 + 1.3) * 0.06,
    0.45,
    1.25,
  );

  windUniforms.time.value = time;
  windUniforms.direction.value.set(Math.cos(angle), Math.sin(angle));
  windUniforms.strength.value = strength;
}

export function isWindMaterial(name: string): boolean {
  return WIND_MATERIALS.has(name);
}

function patchWindVertex(shader: THREE.WebGLProgramParametersWithUniforms): void {
  shader.uniforms.uWindTime = windUniforms.time;
  shader.uniforms.uWindDirection = windUniforms.direction;
  shader.uniforms.uWindStrength = windUniforms.strength;
  shader.vertexShader = shader.vertexShader
    .replace(
      'void main() {',
      /* glsl */ `
        uniform float uWindTime;
        uniform vec2 uWindDirection;
        uniform float uWindStrength;
        void main() {
      `,
    )
    .replace(
      '#include <begin_vertex>',
      /* glsl */ `
        #include <begin_vertex>
        {
          vec4 dlWindWorld = modelMatrix * vec4( transformed, 1.0 );
          float dlWindHeight = clamp( ( dlWindWorld.y - 0.55 ) / 5.5, 0.0, 1.0 );
          float dlWindWeight = dlWindHeight * dlWindHeight;
          float dlWindWave = sin( uWindTime * 1.55 + dlWindWorld.x * 0.33 + dlWindWorld.z * 0.27 );
          float dlWindFlutter = sin( uWindTime * 3.1 + dlWindWorld.x * 0.71 + dlWindWorld.y * 0.9 );
          float dlWindAmount = ( dlWindWave * 0.62 + dlWindFlutter * 0.18 + 0.42 )
            * dlWindWeight * uWindStrength;
          transformed.x += uWindDirection.x * dlWindAmount * 0.22;
          transformed.z += uWindDirection.y * dlWindAmount * 0.22;
          transformed.y += dlWindFlutter * dlWindWeight * uWindStrength * 0.035;
        }
      `,
    );
}

/** Bend leaves and palm fronds. The height weight keeps trunks and litter still. */
export function applyWindSway<M extends THREE.Material>(material: M): M {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    patchWindVertex(shader);
  };
  const previousKey = material.customProgramCacheKey.bind(material);
  material.customProgramCacheKey = () => `${previousKey()}-wind`;
  material.needsUpdate = true;
  return material;
}

function patchSeaVertex(shader: THREE.WebGLProgramParametersWithUniforms): void {
  shader.uniforms.uWindTime = windUniforms.time;
  shader.uniforms.uWindDirection = windUniforms.direction;
  shader.uniforms.uWindStrength = windUniforms.strength;
  shader.vertexShader = shader.vertexShader
    .replace(
      'void main() {',
      /* glsl */ `
        uniform float uWindTime;
        uniform vec2 uWindDirection;
        uniform float uWindStrength;
        void main() {
      `,
    )
    .replace(
      '#include <begin_vertex>',
      /* glsl */ `
        #include <begin_vertex>
        {
          vec4 dlSeaWorld = modelMatrix * vec4( transformed, 1.0 );
          float dlSeaWave =
            sin( dlSeaWorld.x * 0.13 + uWindTime * 0.85 ) * 0.075 +
            sin( dlSeaWorld.z * 0.17 - uWindTime * 1.05 ) * 0.055 +
            sin( ( dlSeaWorld.x + dlSeaWorld.z ) * 0.31 + uWindTime * 1.7 ) * 0.022;
          transformed.y += dlSeaWave * uWindStrength;
          transformed.xz += uWindDirection * dlSeaWave * uWindStrength * 0.35;
        }
      `,
    );
}

/** Tiny travelling ripples so the large sea planes do not read as glass. */
export function applySeaMotion<M extends THREE.Material>(material: M): M {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    patchSeaVertex(shader);
  };
  const previousKey = material.customProgramCacheKey.bind(material);
  material.customProgramCacheKey = () => `${previousKey()}-sea`;
  material.needsUpdate = true;
  return material;
}

function patchFoamVertex(shader: THREE.WebGLProgramParametersWithUniforms): void {
  shader.uniforms.uWindTime = windUniforms.time;
  shader.uniforms.uWindDirection = windUniforms.direction;
  shader.uniforms.uWindStrength = windUniforms.strength;
  shader.vertexShader = shader.vertexShader
    .replace(
      'void main() {',
      /* glsl */ `
        uniform float uWindTime;
        uniform vec2 uWindDirection;
        uniform float uWindStrength;
        void main() {
      `,
    )
    .replace(
      '#include <begin_vertex>',
      /* glsl */ `
        #include <begin_vertex>
        {
          vec4 dlFoamWorld = modelMatrix * vec4( transformed, 1.0 );
          float dlFoamRoll = sin( uWindTime * 1.15 + dlFoamWorld.x * 0.07 + dlFoamWorld.z * 0.12 );
          float dlFoamLift = sin( uWindTime * 2.2 + dlFoamWorld.x * 0.42 ) * 0.018;
          transformed.xz += uWindDirection * ( dlFoamRoll * 0.5 + 0.5 ) * uWindStrength * 0.5;
          transformed.y += dlFoamLift * uWindStrength;
        }
      `,
    );
}

/** Foam slides up the sand on the same onshore push as the leaves. */
export function applyFoamMotion<M extends THREE.Material>(material: M): M {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    patchFoamVertex(shader);
  };
  const previousKey = material.customProgramCacheKey.bind(material);
  material.customProgramCacheKey = () => `${previousKey()}-foam`;
  material.needsUpdate = true;
  return material;
}

/** Shadow depth material that sways with the foliage it belongs to. */
export function createWindDepthMaterial(curve: CurveUniforms): THREE.MeshDepthMaterial {
  return applyWindSway(createCurvedDepthMaterial(curve));
}
