import * as THREE from 'three';

/**
 * The curved world effect bends geometry away from the player on the GPU.
 *
 * Physics, collision, and gameplay stay completely flat. Only the rendered
 * position is displaced, which keeps movement predictable while the eye sees
 * a small planet. The same patch is applied to shadow depth materials so
 * shadows follow the curve instead of floating above it.
 *
 * A short start radius keeps the street under the player flat, and the normal
 * patch keeps light falling correctly on the tilted ground further out.
 */
export interface CurveUniforms {
  strength: { value: number };
  start: { value: number };
  center: { value: THREE.Vector2 };
}

/** Drop in metres at radius 110 with the default setting of 1. */
const BASE_STRENGTH = 0.0012;
const START_RADIUS = 12;

export function createCurveUniforms(strength = BASE_STRENGTH): CurveUniforms {
  return {
    strength: { value: strength },
    start: { value: START_RADIUS },
    center: { value: new THREE.Vector2(0, 0) },
  };
}

const PROJECT_VERTEX = '#include <project_vertex>';
const BEGIN_NORMAL = '#include <beginnormal_vertex>';

const CURVED_PROJECT = /* glsl */ `
  vec4 dlWorldPosition = modelMatrix * vec4( transformed, 1.0 );
  float dlCurveDistance = distance( dlWorldPosition.xz, uCurveCenter );
  float dlCurveDelta = max( 0.0, dlCurveDistance - uCurveStart );
  dlWorldPosition.y -= uCurveStrength * dlCurveDelta * dlCurveDelta;
  vec4 mvPosition = viewMatrix * dlWorldPosition;
  gl_Position = projectionMatrix * mvPosition;
`;

const CURVED_NORMAL = /* glsl */ `
  vec3 objectNormal = vec3( normal );
  {
    vec4 dlNormalPosition = modelMatrix * vec4( position, 1.0 );
    float dlNormalDistance = distance( dlNormalPosition.xz, uCurveCenter );
    float dlNormalDelta = max( 0.0, dlNormalDistance - uCurveStart );
    vec2 dlNormalDirection = dlNormalDistance > 1e-4
      ? ( dlNormalPosition.xz - uCurveCenter ) / dlNormalDistance
      : vec2( 0.0 );
    float dlNormalSlope = 2.0 * uCurveStrength * dlNormalDelta;
    vec3 dlGroundNormal = normalize( vec3( dlNormalSlope * dlNormalDirection.x, 1.0, dlNormalSlope * dlNormalDirection.y ) );
    float dlNormalBlend = smoothstep( 0.35, 0.8, objectNormal.y ) * smoothstep( 0.0, 4.0, dlNormalDelta );
    objectNormal = normalize( mix( objectNormal, dlGroundNormal, dlNormalBlend ) );
  }
`;

function patchVertexShader(shader: THREE.WebGLProgramParametersWithUniforms, uniforms: CurveUniforms): void {
  shader.uniforms.uCurveStrength = uniforms.strength;
  shader.uniforms.uCurveStart = uniforms.start;
  shader.uniforms.uCurveCenter = uniforms.center;
  shader.vertexShader = shader.vertexShader
    .replace(
      'void main() {',
      /* glsl */ `
        uniform float uCurveStrength;
        uniform float uCurveStart;
        uniform vec2 uCurveCenter;
        void main() {
      `,
    )
    .replace(BEGIN_NORMAL, CURVED_NORMAL)
    .replace(PROJECT_VERTEX, CURVED_PROJECT);
}

export function applyCurvedWorld<M extends THREE.Material>(material: M, uniforms: CurveUniforms): M {
  const previous = material.onBeforeCompile;
  material.onBeforeCompile = (shader, renderer) => {
    previous?.call(material, shader, renderer);
    patchVertexShader(shader, uniforms);
  };
  material.customProgramCacheKey = () => 'daily-life-curved';
  material.needsUpdate = true;
  return material;
}

/** Depth material used for shadow casting, patched with the same bend. */
export function createCurvedDepthMaterial(uniforms: CurveUniforms): THREE.MeshDepthMaterial {
  const material = new THREE.MeshDepthMaterial({
    depthPacking: THREE.RGBADepthPacking,
    side: THREE.DoubleSide,
  });
  return applyCurvedWorld(material, uniforms);
}

export function setCurveStrength(uniforms: CurveUniforms, value: number): void {
  uniforms.strength.value = value * BASE_STRENGTH;
}

export function setCurveCenter(uniforms: CurveUniforms, x: number, z: number): void {
  uniforms.center.value.set(x, z);
}
