import * as THREE from 'three';
import type { Quality } from '../core/settings';
import { setCurveCenter, type CurveUniforms } from './curved';
import { animateWater, setWindowGlow, type MaterialSet } from './materials';
import { paletteAt, Sky, sunDirectionAt } from './sky';

export interface SceneContext {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  sun: THREE.DirectionalLight;
  hemi: THREE.HemisphereLight;
  fill: THREE.DirectionalLight;
  sky: Sky;
  curve: CurveUniforms;
}

export function createSceneContext(canvas: HTMLCanvasElement, quality: Quality, curve: CurveUniforms): SceneContext {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: quality === 'high',
    powerPreference: 'high-performance',
    stencil: false,
  });
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0xb9c4c0, 0.0052);

  const camera = new THREE.PerspectiveCamera(48, 1, 0.1, 420);
  camera.position.set(4, 4, 34);

  const sun = new THREE.DirectionalLight(0xfff0d8, 2);
  sun.castShadow = true;
  // Long, low-angle shadows need a slightly larger normal bias than noon.
  sun.shadow.bias = -0.0003;
  sun.shadow.normalBias = 0.04;
  sun.shadow.mapSize.set(2048, 2048);
  const shadowCamera = sun.shadow.camera as THREE.OrthographicCamera;
  shadowCamera.left = -42;
  shadowCamera.right = 42;
  shadowCamera.top = 42;
  shadowCamera.bottom = -42;
  shadowCamera.near = 1;
  shadowCamera.far = 190;
  shadowCamera.updateProjectionMatrix();
  scene.add(sun);
  scene.add(sun.target);

  const hemi = new THREE.HemisphereLight(0xd7e0e6, 0x55503f, 0.6);
  scene.add(hemi);

  // A shadowless fill from the opposite side keeps facades readable when the
  // player walks into a street the sun has already left.
  const fill = new THREE.DirectionalLight(0xc9d8e0, 0.35);
  fill.position.set(-24, 30, -20);
  scene.add(fill);
  scene.add(fill.target);

  const sky = new Sky();
  scene.add(sky.mesh);

  applyQuality(renderer, sun, quality);
  resize(renderer, camera);

  return { renderer, scene, camera, sun, hemi, fill, sky, curve };
}

export function applyQuality(renderer: THREE.WebGLRenderer, sun: THREE.DirectionalLight, quality: Quality): void {
  const ratio = typeof window === 'undefined' ? 1 : window.devicePixelRatio || 1;
  renderer.setPixelRatio(quality === 'high' ? Math.min(ratio, 2) : Math.min(ratio, 1.25));
  renderer.shadowMap.enabled = true;
  const size = quality === 'high' ? 2048 : 1024;
  if (sun.shadow.mapSize.x !== size) {
    sun.shadow.mapSize.set(size, size);
    sun.shadow.map?.dispose();
    sun.shadow.map = null;
  }
  const shadowCamera = sun.shadow.camera as THREE.OrthographicCamera;
  const extent = quality === 'high' ? 42 : 32;
  if (shadowCamera.right !== extent) {
    shadowCamera.left = -extent;
    shadowCamera.right = extent;
    shadowCamera.top = extent;
    shadowCamera.bottom = -extent;
    shadowCamera.updateProjectionMatrix();
  }
}

export function resize(renderer: THREE.WebGLRenderer, camera: THREE.PerspectiveCamera): void {
  const width = window.innerWidth;
  const height = window.innerHeight;
  renderer.setSize(width, height, false);
  camera.aspect = width / Math.max(1, height);
  camera.updateProjectionMatrix();
}

const sunDir = new THREE.Vector3();
const WHITE = new THREE.Color(0xffffff);

export interface EnvironmentState {
  minutes: number;
  playerPosition: THREE.Vector3;
}

/**
 * One environment update per frame. The palette drives the sky, fog, sun,
 * ambient fill, exposure, and the warmth of windows and street lamps, so the
 * whole town changes mood together rather than in isolated pieces.
 */
export function updateEnvironment(
  context: SceneContext,
  materials: MaterialSet,
  state: EnvironmentState,
): void {
  const palette = paletteAt(state.minutes);
  const direction = sunDirectionAt(state.minutes, sunDir);

  context.sky.update(context.camera, palette, direction);

  context.scene.fog?.color.copy(palette.fog);
  context.renderer.toneMappingExposure = palette.exposure;

  // Colour and strength both come from solar elevation, so a low sun is warm
  // and weak while noon is neutral and bright without separate keyframes.
  context.sun.color.copy(palette.sun);
  context.sun.intensity = palette.sunIntensity;
  const lowSun = 1 - Math.min(1, Math.max(0, direction.y * 4));
  context.sun.shadow.bias = -0.00034 + lowSun * 0.00008;
  context.sun.position.copy(state.playerPosition).addScaledVector(direction, 80);
  context.sun.target.position.copy(state.playerPosition);
  context.sun.target.updateMatrixWorld();

  context.hemi.color.copy(palette.top).lerp(WHITE, 0.35);
  context.hemi.groundColor.copy(palette.ground);
  context.hemi.intensity = palette.hemiIntensity;

  // Fill comes from the opposite side of the sun, so shaded streets still
  // show the shape of walls and window frames. It cools down after dusk.
  context.fill.color.copy(palette.horizon).lerp(WHITE, 0.45);
  context.fill.intensity = (0.16 + palette.hemiIntensity * 0.16) * (1 - palette.night * 0.55);
  context.fill.position.set(
    state.playerPosition.x - direction.x * 35,
    state.playerPosition.y + 26,
    state.playerPosition.z - direction.z * 35,
  );
  context.fill.target.position.copy(state.playerPosition);
  context.fill.target.updateMatrixWorld();

  setWindowGlow(materials, palette.glow);
  animateWater(materials);
  setCurveCenter(context.curve, state.playerPosition.x, state.playerPosition.z);
}
