import type { DayPhase } from './clock';

/**
 * Small procedural soundscape. No audio files are shipped: wind is filtered
 * noise, birds are short sine chirps, footsteps are filtered noise bursts.
 * The context is only created after a user gesture so autoplay policies are
 * respected.
 */
export class Ambience {
  private context: AudioContext | null = null;
  private master: GainNode | null = null;
  private windGain: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private birdTimer = 4;
  private cricketTimer = 2;
  private volume = 0.7;
  private phase: DayPhase = 'morning';

  async start(): Promise<void> {
    if (this.context) {
      if (this.context.state === 'suspended') await this.context.resume();
      return;
    }
    const Context = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Context) return;

    const context = new Context();
    this.context = context;

    const master = context.createGain();
    master.gain.value = this.volume * 0.55;
    master.connect(context.destination);
    this.master = master;

    const noise = context.createBuffer(1, context.sampleRate * 2, context.sampleRate);
    const data = noise.getChannelData(0);
    for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
    this.noise = noise;

    const wind = context.createBufferSource();
    wind.buffer = noise;
    wind.loop = true;
    const windFilter = context.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 520;
    windFilter.Q.value = 0.4;
    const windGain = context.createGain();
    windGain.gain.value = 0.045;
    wind.connect(windFilter).connect(windGain).connect(master);
    wind.start();
    this.windGain = windGain;

    if (context.state === 'suspended') await context.resume();
  }

  setVolume(value: number): void {
    this.volume = Math.max(0, Math.min(1, value));
    if (this.master && this.context) {
      this.master.gain.setTargetAtTime(this.volume * 0.55, this.context.currentTime, 0.08);
    }
  }

  update(dt: number, phase: DayPhase): void {
    this.phase = phase;
    if (!this.context || !this.noise) return;

    this.birdTimer -= dt;
    this.cricketTimer -= dt;

    if ((phase === 'morning' || phase === 'day') && this.birdTimer <= 0) {
      this.birdTimer = 5 + Math.random() * 9;
      this.chirp();
    }

    if (phase === 'night' && this.cricketTimer <= 0) {
      this.cricketTimer = 1.4 + Math.random() * 2.4;
      this.cricket();
    }

    if (this.windGain && this.context) {
      const target =
        phase === 'night' ? 0.026 : phase === 'evening' ? 0.05 : 0.042;
      this.windGain.gain.setTargetAtTime(target, this.context.currentTime, 0.8);
    }
  }

  footstep(running: boolean): void {
    if (!this.context || !this.noise || !this.master) return;
    const context = this.context;
    const source = context.createBufferSource();
    source.buffer = this.noise;
    source.playbackRate.value = 0.7 + Math.random() * 0.3;

    const filter = context.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 900 + Math.random() * 350;
    filter.Q.value = 0.9;

    const gain = context.createGain();
    const now = context.currentTime;
    const peak = running ? 0.075 : 0.05;
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(peak, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.11);

    source.connect(filter).connect(gain).connect(this.master);
    source.start(now, Math.random() * 1.4, 0.14);
  }

  private chirp(): void {
    if (!this.context || !this.master) return;
    const context = this.context;
    const now = context.currentTime;
    const notes = 2 + Math.floor(Math.random() * 3);
    for (let i = 0; i < notes; i += 1) {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = 'sine';
      const start = now + i * 0.11;
      const base = 2400 + Math.random() * 900;
      oscillator.frequency.setValueAtTime(base, start);
      oscillator.frequency.exponentialRampToValueAtTime(base * 1.28, start + 0.05);
      oscillator.frequency.exponentialRampToValueAtTime(base * 0.92, start + 0.1);
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.012, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.12);
      oscillator.connect(gain).connect(this.master);
      oscillator.start(start);
      oscillator.stop(start + 0.14);
    }
  }

  private cricket(): void {
    if (!this.context || !this.master || !this.noise) return;
    const context = this.context;
    const now = context.currentTime;
    const source = context.createBufferSource();
    source.buffer = this.noise;
    const filter = context.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 4200;
    filter.Q.value = 6;
    const gain = context.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.008, now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.16);
    source.connect(filter).connect(gain).connect(this.master);
    source.start(now, Math.random(), 0.18);
  }

  /** Chime used when an activity is completed or the day rolls over. */
  bell(): void {
    if (!this.context || !this.master) return;
    const context = this.context;
    const now = context.currentTime;
    const notes = [523.25, 659.25, 783.99];
    notes.forEach((frequency, index) => {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.value = frequency;
      const start = now + index * 0.09;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.035, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 1.1);
      oscillator.connect(gain).connect(this.master!);
      oscillator.start(start);
      oscillator.stop(start + 1.15);
    });
  }

  dispose(): void {
    this.context?.close();
    this.context = null;
    this.master = null;
    this.windGain = null;
    this.noise = null;
  }
}
