export interface BubbleView {
  id: string;
  text: string;
  /** Screen-space position of the point above the speaker's head. */
  x: number;
  y: number;
  visible: boolean;
}

/**
 * DOM speech bubbles that follow characters in screen space. The text stays
 * crisp at any render scale and reuses the dialog font, which a canvas sprite
 * would not do as cleanly.
 */
export class BubbleLayer {
  private readonly root: HTMLElement;
  private readonly elements = new Map<string, HTMLElement>();

  constructor(root: HTMLElement | null = document.getElementById('bubbles')) {
    if (!root) throw new Error('Missing #bubbles');
    this.root = root;
  }

  update(views: readonly BubbleView[]): void {
    const active = new Set<string>();
    for (const view of views) {
      active.add(view.id);
      let element = this.elements.get(view.id);
      if (!element) {
        element = document.createElement('div');
        element.className = 'bubble';
        element.dataset.speaker = view.id;
        this.root.append(element);
        this.elements.set(view.id, element);
      }
      if (element.textContent !== view.text) element.textContent = view.text;
      element.style.left = `${Math.round(view.x)}px`;
      element.style.top = `${Math.round(view.y)}px`;
      element.classList.toggle('is-visible', view.visible);
    }

    for (const [id, element] of this.elements) {
      if (active.has(id)) continue;
      element.remove();
      this.elements.delete(id);
    }
  }
}
