import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { assetUrl } from '../core/assets';
import type { CurveUniforms } from '../render/curved';
import { createCurvedDepthMaterial } from '../render/curved';
import { createTownMaterials, type MaterialSet } from '../render/materials';
import { prepareSignFonts } from '../render/textures';
import { createWindDepthMaterial, isWindMaterial } from '../render/wind';
import { CollisionWorld, type TownLayout } from './collision';

export interface Town {
  root: THREE.Group;
  layout: TownLayout;
  materials: MaterialSet;
  collision: CollisionWorld;
  dispose(): void;
}

export interface TownProgress {
  (fraction: number, stage: 'world' | 'layout'): void;
}

export async function loadTown(curve: CurveUniforms, onProgress?: TownProgress): Promise<Town> {
  const layoutPromise = fetch(assetUrl('assets/town-layout.json'))
    .then((response) => {
      if (!response.ok) throw new Error(`Layout request failed: ${response.status}`);
      return response.json() as Promise<TownLayout>;
    })
    .then((layout) => {
      onProgress?.(1, 'layout');
      return layout;
    });

  const loader = new GLTFLoader();
  loader.setMeshoptDecoder(MeshoptDecoder);

  // Canvas signage is painted in the same frame as the town build, so load the
  // webfonts before any texture is baked.
  await prepareSignFonts();

  const materials = createTownMaterials(curve);
  const depthMaterial = createCurvedDepthMaterial(curve);
  // Leaves need their own depth material: the shared one keeps building
  // shadows still, while this one sways with the same wind as the foliage.
  const windDepthMaterial = createWindDepthMaterial(curve);
  const fallback = new THREE.MeshStandardMaterial({ color: 0x9a948a, roughness: 0.95 });

  const gltf = await loader.loadAsync(assetUrl('assets/models/town.glb'), (event) => {
    if (event.total > 0) onProgress?.(Math.min(1, event.loaded / event.total), 'world');
  });

  const root = new THREE.Group();
  root.name = 'Town';
  root.add(gltf.scene);

  gltf.scene.traverse((object) => {
    if (!(object instanceof THREE.Mesh)) return;
    const source = Array.isArray(object.material) ? object.material : [object.material];
    const mapped = source.map((material) => {
      const name = (material as THREE.Material).name;
      return materials.town.get(name) ?? fallback;
    });
    object.material = Array.isArray(object.material) ? mapped : mapped[0];
    object.castShadow = true;
    object.receiveShadow = true;
    object.customDepthMaterial = mapped.some((material) => isWindMaterial(material.name))
      ? windDepthMaterial
      : depthMaterial;
    object.frustumCulled = true;

    // The town is a static backdrop; skip per-frame matrix work for it.
    object.updateMatrix();
    object.matrixAutoUpdate = false;
  });

  const layout = await layoutPromise;
  const collision = new CollisionWorld(layout);

  return {
    root,
    layout,
    materials,
    collision,
    dispose() {
      root.traverse((object) => {
        if (object instanceof THREE.Mesh) {
          object.geometry.dispose();
        }
      });
      materials.dispose();
      depthMaterial.dispose();
      windDepthMaterial.dispose();
      fallback.dispose();
    },
  };
}
