import type { CharacterId } from '../characters/catalog';

/**
 * Small painted busts for the dialog panel. The in-game characters are stylised
 * low-poly figures, so the portrait is drawn as flat colour shapes rather than
 * a filtered render: it stays crisp at any size and costs nothing at runtime.
 */

export type PortraitSpec =
  | { kind: 'character'; id: CharacterId }
  | { kind: 'flavor'; id: string }
  | { kind: 'letter'; text: string };

interface Palette {
  skin: string;
  hair: string;
  top: string;
  accent: string;
  hairStyle: 'short' | 'bob' | 'wavy';
  glasses: boolean;
  beard: boolean;
  cap?: string;
}

const PALETTES: Record<CharacterId, Palette> = {
  male_1: {
    skin: '#c99a78',
    hair: '#211a16',
    top: '#27324a',
    accent: '#e5ddcc',
    hairStyle: 'short',
    glasses: true,
    beard: false,
  },
  male_2: {
    skin: '#d3a889',
    hair: '#241c17',
    top: '#eee9dc',
    accent: '#f7f3e8',
    hairStyle: 'short',
    glasses: true,
    beard: false,
    cap: '#2c2d2b',
  },
  male_3: {
    skin: '#b98767',
    hair: '#201915',
    top: '#e7e1d4',
    accent: '#e7e1d4',
    hairStyle: 'short',
    glasses: false,
    beard: true,
  },
  female_1: {
    skin: '#e0b393',
    hair: '#241a16',
    top: '#d8cbb4',
    accent: '#f0e9da',
    hairStyle: 'bob',
    glasses: true,
    beard: false,
  },
  female_2: {
    skin: '#e5bba0',
    hair: '#2b211b',
    top: '#e9e2d4',
    accent: '#efece3',
    hairStyle: 'short',
    glasses: true,
    beard: false,
    cap: '#f1ede4',
  },
  female_3: {
    skin: '#e1b69a',
    hair: '#35251d',
    top: '#8b8781',
    accent: '#f1ede4',
    hairStyle: 'wavy',
    glasses: false,
    beard: false,
  },
};

const INK = '#2f3a33';

function rgb(hex: string): [number, number, number] {
  const value = hex.replace('#', '');
  return [
    parseInt(value.slice(0, 2), 16),
    parseInt(value.slice(2, 4), 16),
    parseInt(value.slice(4, 6), 16),
  ];
}

function mix(a: string, b: string, t: number): string {
  const [r1, g1, b1] = rgb(a);
  const [r2, g2, b2] = rgb(b);
  const channel = (x: number, y: number) => Math.round(x + (y - x) * t);
  return `rgb(${channel(r1, r2)}, ${channel(g1, g2)}, ${channel(b1, b2)})`;
}

function shade(hex: string, amount: number): string {
  return mix(hex, '#101510', amount);
}

export function drawPortrait(canvas: HTMLCanvasElement, spec: PortraitSpec): void {
  const size = 192;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.clearRect(0, 0, size, size);

  if (spec.kind === 'flavor') {
    drawFlavor(ctx, size, spec.id);
    return;
  }
  if (spec.kind === 'letter') {
    drawLetter(ctx, size, spec.text);
    return;
  }
  drawCharacter(ctx, size, PALETTES[spec.id]);
}

function backdrop(ctx: CanvasRenderingContext2D, size: number, base: string): void {
  const gradient = ctx.createLinearGradient(0, 0, size, size);
  gradient.addColorStop(0, mix(base, '#ffffff', 0.42));
  gradient.addColorStop(0.62, mix(base, '#000000', 0.06));
  gradient.addColorStop(1, shade(base, 0.34));
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);

  // Soft window light from the upper left, matching the town's morning key.
  const glow = ctx.createRadialGradient(size * 0.22, size * 0.12, 2, size * 0.22, size * 0.12, size * 0.9);
  glow.addColorStop(0, 'rgba(255, 248, 232, 0.55)');
  glow.addColorStop(1, 'rgba(255, 248, 232, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, size, size);
}

function drawCharacter(ctx: CanvasRenderingContext2D, size: number, palette: Palette): void {
  const s = size / 192;
  backdrop(ctx, size, palette.top);

  const cx = 96 * s;
  const headY = 78 * s;
  const headRx = 40 * s;
  const headRy = 49 * s;

  // Shoulders and clothing.
  ctx.fillStyle = palette.top;
  ctx.beginPath();
  ctx.moveTo(6 * s, 192 * s);
  ctx.quadraticCurveTo(12 * s, 139 * s, 54 * s, 126 * s);
  ctx.lineTo(138 * s, 126 * s);
  ctx.quadraticCurveTo(180 * s, 139 * s, 186 * s, 192 * s);
  ctx.closePath();
  ctx.fill();

  // Collar in the accent fabric.
  ctx.fillStyle = palette.accent;
  ctx.beginPath();
  ctx.moveTo(58 * s, 126 * s);
  ctx.lineTo(cx, 154 * s);
  ctx.lineTo(134 * s, 126 * s);
  ctx.lineTo(122 * s, 122 * s);
  ctx.lineTo(cx, 143 * s);
  ctx.lineTo(70 * s, 122 * s);
  ctx.closePath();
  ctx.fill();

  // Neck, with a soft contact shadow under the jaw.
  ctx.fillStyle = palette.skin;
  ctx.beginPath();
  ctx.roundRect(81 * s, 108 * s, 30 * s, 30 * s, 9 * s);
  ctx.fill();
  ctx.fillStyle = shade(palette.skin, 0.2);
  ctx.beginPath();
  ctx.ellipse(cx, 112 * s, 15 * s, 6 * s, 0, 0, Math.PI);
  ctx.fill();

  // Hair mass behind the face.
  ctx.fillStyle = palette.hair;
  ctx.beginPath();
  ctx.ellipse(cx, headY - 4 * s, headRx + 5 * s, headRy + 4 * s, 0, 0, Math.PI * 2);
  ctx.fill();

  if (palette.hairStyle === 'bob' || palette.hairStyle === 'wavy') {
    const drop = palette.hairStyle === 'bob' ? 50 * s : 44 * s;
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(
        cx + side * (headRx - 2 * s),
        headY + 16 * s,
        14 * s,
        drop,
        side * 0.08,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
  }

  // Ears.
  ctx.fillStyle = shade(palette.skin, 0.08);
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(cx + side * (headRx - 1 * s), headY + 10 * s, 6 * s, 10 * s, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // Face.
  const face = ctx.createLinearGradient(cx - headRx, 0, cx + headRx, 0);
  face.addColorStop(0, mix(palette.skin, '#ffffff', 0.12));
  face.addColorStop(0.6, palette.skin);
  face.addColorStop(1, shade(palette.skin, 0.16));
  ctx.fillStyle = face;
  ctx.beginPath();
  ctx.ellipse(cx, headY + 4 * s, headRx, headRy, 0, 0, Math.PI * 2);
  ctx.fill();

  // Fringe.
  ctx.fillStyle = palette.hair;
  ctx.beginPath();
  ctx.moveTo(cx - headRx - 2 * s, headY - 6 * s);
  ctx.quadraticCurveTo(cx - headRx + 2 * s, headY - 52 * s, cx, headY - 50 * s);
  ctx.quadraticCurveTo(cx + headRx - 2 * s, headY - 52 * s, cx + headRx + 2 * s, headY - 6 * s);
  ctx.quadraticCurveTo(cx + 22 * s, headY - 30 * s, cx + 4 * s, headY - 24 * s);
  ctx.quadraticCurveTo(cx - 18 * s, headY - 18 * s, cx - headRx - 2 * s, headY - 6 * s);
  ctx.closePath();
  ctx.fill();

  if (palette.hairStyle === 'short') {
    // Short sideburns.
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(cx + side * (headRx - 2 * s), headY - 6 * s, 8 * s, 22 * s, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Eyebrows.
  ctx.strokeStyle = shade(palette.hair, 0.12);
  ctx.lineWidth = 3.2 * s;
  ctx.lineCap = 'round';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(cx + side * 9 * s, headY - 12 * s);
    ctx.quadraticCurveTo(cx + side * 20 * s, headY - 18 * s, cx + side * 30 * s, headY - 12 * s);
    ctx.stroke();
  }

  // Eyes.
  for (const side of [-1, 1]) {
    const ex = cx + side * 19 * s;
    ctx.fillStyle = '#f6f1e7';
    ctx.beginPath();
    ctx.ellipse(ex, headY + 3 * s, 9.4 * s, 6.4 * s, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#3a2a1e';
    ctx.beginPath();
    ctx.arc(ex + side * 0.6 * s, headY + 3.4 * s, 3.6 * s, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#fdfaf4';
    ctx.beginPath();
    ctx.arc(ex + side * 1.8 * s, headY + 1.9 * s, 1.2 * s, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = shade(palette.hair, 0.1);
    ctx.lineWidth = 1.8 * s;
    ctx.beginPath();
    ctx.arc(ex, headY + 3 * s, 9.2 * s, Math.PI * 1.08, Math.PI * 1.92);
    ctx.stroke();
  }

  // Nose and mouth.
  ctx.strokeStyle = shade(palette.skin, 0.26);
  ctx.lineWidth = 2.4 * s;
  ctx.beginPath();
  ctx.moveTo(cx + 1 * s, headY + 10 * s);
  ctx.quadraticCurveTo(cx + 4.5 * s, headY + 19 * s, cx - 1 * s, headY + 21 * s);
  ctx.stroke();

  ctx.strokeStyle = '#8c5f58';
  ctx.lineWidth = 3 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 9 * s, headY + 31 * s);
  ctx.quadraticCurveTo(cx, headY + 35.5 * s, cx + 9 * s, headY + 31 * s);
  ctx.stroke();

  if (palette.beard) {
    ctx.fillStyle = mix(palette.hair, palette.skin, 0.18);
    ctx.beginPath();
    ctx.moveTo(cx - 31 * s, headY + 16 * s);
    ctx.quadraticCurveTo(cx - 28 * s, headY + 48 * s, cx, headY + 50 * s);
    ctx.quadraticCurveTo(cx + 28 * s, headY + 48 * s, cx + 31 * s, headY + 16 * s);
    ctx.quadraticCurveTo(cx + 20 * s, headY + 38 * s, cx, headY + 39 * s);
    ctx.quadraticCurveTo(cx - 20 * s, headY + 38 * s, cx - 31 * s, headY + 16 * s);
    ctx.closePath();
    ctx.fill();
  }

  if (palette.glasses) {
    ctx.strokeStyle = '#2d2c29';
    ctx.lineWidth = 2.6 * s;
    for (const side of [-1, 1]) {
      const ex = cx + side * 19 * s;
      ctx.beginPath();
      ctx.roundRect(ex - 13 * s, headY - 5 * s, 26 * s, 17 * s, 5 * s);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(cx - 5 * s, headY + 2 * s);
    ctx.lineTo(cx + 5 * s, headY + 2 * s);
    ctx.stroke();
  }

  if (palette.cap) {
    ctx.fillStyle = palette.cap;
    ctx.beginPath();
    ctx.ellipse(cx, headY - 32 * s, headRx + 3 * s, 22 * s, 0, Math.PI, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.roundRect(cx - headRx - 2 * s, headY - 36 * s, (headRx + 2 * s) * 2, 10 * s, 4 * s);
    ctx.fill();
    ctx.fillStyle = shade(palette.cap, 0.18);
    ctx.beginPath();
    ctx.ellipse(cx, headY - 30 * s, headRx + 4 * s, 6 * s, 0, 0, Math.PI);
    ctx.fill();
  }

  // Frame.
  ctx.strokeStyle = 'rgba(26, 32, 27, 0.35)';
  ctx.lineWidth = 2 * s;
  ctx.strokeRect(1 * s, 1 * s, size - 2 * s, size - 2 * s);
}

function drawFlavor(ctx: CanvasRenderingContext2D, size: number, id: string): void {
  const s = size / 192;
  backdrop(ctx, size, '#d9d2c0');

  // A thin inner frame keeps the portraits consistent with the character busts.
  ctx.strokeStyle = 'rgba(47, 58, 51, 0.28)';
  ctx.lineWidth = 1.5 * s;
  ctx.strokeRect(10 * s, 10 * s, size - 20 * s, size - 20 * s);

  ctx.save();
  ctx.translate(96 * s, 96 * s);
  ctx.strokeStyle = INK;
  ctx.fillStyle = 'rgba(47, 58, 51, 0.12)';
  ctx.lineWidth = 3.4 * s;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  if (id === 'fountain') {
    ctx.beginPath();
    ctx.ellipse(0, 40 * s, 42 * s, 12 * s, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-30 * s, 38 * s);
    ctx.quadraticCurveTo(-30 * s, 2 * s, -10 * s, -8 * s);
    ctx.moveTo(30 * s, 38 * s);
    ctx.quadraticCurveTo(30 * s, 2 * s, 10 * s, -8 * s);
    ctx.moveTo(0, 38 * s);
    ctx.lineTo(0, -16 * s);
    ctx.stroke();
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(side * 8 * s, -16 * s);
      ctx.quadraticCurveTo(side * 24 * s, -34 * s, side * 16 * s, -52 * s);
      ctx.stroke();
    }
  } else if (id === 'cafe') {
    ctx.beginPath();
    ctx.roundRect(-30 * s, -16 * s, 50 * s, 44 * s, 10 * s);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(22 * s, 4 * s, 12 * s, -Math.PI * 0.5, Math.PI * 0.5);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(0, 38 * s, 34 * s, 7 * s, 0, 0, Math.PI * 2);
    ctx.stroke();
    for (const x of [-16, 0, 16]) {
      ctx.beginPath();
      ctx.moveTo(x * s, -28 * s);
      ctx.quadraticCurveTo((x + 8) * s, -40 * s, x * s, -52 * s);
      ctx.stroke();
    }
  } else if (id === 'bakery') {
    ctx.beginPath();
    ctx.moveTo(-44 * s, 28 * s);
    ctx.quadraticCurveTo(-44 * s, -24 * s, 0, -24 * s);
    ctx.quadraticCurveTo(44 * s, -24 * s, 44 * s, 28 * s);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    for (const x of [-20, 0, 20]) {
      ctx.beginPath();
      ctx.moveTo(x * s, -10 * s);
      ctx.lineTo((x + 8) * s, 18 * s);
      ctx.stroke();
    }
  } else if (id === 'florist') {
    ctx.beginPath();
    ctx.moveTo(0, 46 * s);
    ctx.quadraticCurveTo(2 * s, 10 * s, 0, -10 * s);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(-16 * s, 20 * s, 16 * s, 8 * s, -0.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    for (let i = 0; i < 6; i += 1) {
      const angle = (i / 6) * Math.PI * 2;
      ctx.beginPath();
      ctx.ellipse(
        Math.cos(angle) * 17 * s,
        -22 * s + Math.sin(angle) * 17 * s,
        10 * s,
        7 * s,
        angle,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(0, -22 * s, 6 * s, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(47, 58, 51, 0.3)';
    ctx.fill();
  } else if (id === 'viewpoint') {
    ctx.beginPath();
    ctx.arc(0, -6 * s, 22 * s, 0, Math.PI * 2);
    ctx.stroke();
    for (let i = 0; i < 8; i += 1) {
      const angle = (i / 8) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * 30 * s, -6 * s + Math.sin(angle) * 30 * s);
      ctx.lineTo(Math.cos(angle) * 40 * s, -6 * s + Math.sin(angle) * 40 * s);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(-56 * s, 40 * s);
    ctx.quadraticCurveTo(-22 * s, 4 * s, 6 * s, 40 * s);
    ctx.moveTo(-6 * s, 40 * s);
    ctx.quadraticCurveTo(26 * s, 12 * s, 56 * s, 40 * s);
    ctx.stroke();
  } else if (id === 'castle') {
    ctx.beginPath();
    ctx.moveTo(-40 * s, 42 * s);
    ctx.lineTo(-40 * s, -28 * s);
    ctx.lineTo(-24 * s, -28 * s);
    ctx.lineTo(-24 * s, -38 * s);
    ctx.lineTo(-12 * s, -38 * s);
    ctx.lineTo(-12 * s, -28 * s);
    ctx.lineTo(12 * s, -28 * s);
    ctx.lineTo(12 * s, -38 * s);
    ctx.lineTo(24 * s, -38 * s);
    ctx.lineTo(24 * s, -28 * s);
    ctx.lineTo(40 * s, -28 * s);
    ctx.lineTo(40 * s, 42 * s);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-10 * s, 42 * s);
    ctx.lineTo(-10 * s, 12 * s);
    ctx.quadraticCurveTo(0, 2 * s, 10 * s, 12 * s);
    ctx.lineTo(10 * s, 42 * s);
    ctx.stroke();
  } else if (id === 'sleep') {
    ctx.beginPath();
    ctx.moveTo(-42 * s, 34 * s);
    ctx.lineTo(0, -8 * s);
    ctx.lineTo(42 * s, 34 * s);
    ctx.stroke();
    ctx.beginPath();
    ctx.roundRect(-26 * s, 6 * s, 52 * s, 38 * s, 3 * s);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-6 * s, 44 * s);
    ctx.lineTo(-6 * s, 22 * s);
    ctx.lineTo(6 * s, 22 * s);
    ctx.lineTo(6 * s, 44 * s);
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.arc(0, 0, 40 * s, 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.restore();
}

function drawLetter(ctx: CanvasRenderingContext2D, size: number, text: string): void {
  const s = size / 192;
  backdrop(ctx, size, '#31453b');
  ctx.fillStyle = '#efe8d9';
  ctx.font = `600 ${86 * s}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text.slice(0, 1).toUpperCase(), size / 2, size / 2 + 4 * s);
}
