import { mulberry32 } from '../core/math';

/** The three drinks the TerrasKastil. bar serves. */
export type CafeItemId = 'hot_latte' | 'hot_matcha_latte' | 'iced_matcha';

export interface CafeMenuItem {
  id: CafeItemId;
  /** Display names are fixed so the barista's confirmation reads naturally. */
  name: string;
  noteKey: string;
  descKey: string;
  /** Reference art the drink model is based on. */
  reference: string;
  hot: boolean;
}

export const CAFE_MENU: readonly CafeMenuItem[] = [
  {
    id: 'hot_latte',
    name: 'Hot Latte',
    noteKey: 'cafe.menu.hotLatte.note',
    descKey: 'cafe.menu.hotLatte.desc',
    reference: './reference/hardsurface/cafe-latte.webp',
    hot: true,
  },
  {
    id: 'hot_matcha_latte',
    name: 'Hot Matcha Latte',
    noteKey: 'cafe.menu.hotMatcha.note',
    descKey: 'cafe.menu.hotMatcha.desc',
    reference: './reference/hardsurface/matcha-latte.avif',
    hot: true,
  },
  {
    id: 'iced_matcha',
    name: 'Iced Matcha',
    noteKey: 'cafe.menu.icedMatcha.note',
    descKey: 'cafe.menu.icedMatcha.desc',
    reference: './reference/hardsurface/ice-matcha-latte.png',
    hot: false,
  },
] as const;

export function findCafeItem(id: string): CafeMenuItem | null {
  return CAFE_MENU.find((item) => item.id === id) ?? null;
}

/** Shift labels mirror the opening hours painted on the bar. */
export type CafeShift = 'morning' | 'day' | 'night';

export interface CafeShiftWindow {
  id: CafeShift;
  start: number;
  end: number;
  labelKey: string;
}

/** 06:00–14:00, 14:00–22:00, 22:00–06:00. The bar never closes. */
export const CAFE_SHIFTS: readonly CafeShiftWindow[] = [
  { id: 'morning', start: 6 * 60, end: 14 * 60, labelKey: 'cafe.shift.morning' },
  { id: 'day', start: 14 * 60, end: 22 * 60, labelKey: 'cafe.shift.day' },
  { id: 'night', start: 22 * 60, end: 6 * 60, labelKey: 'cafe.shift.night' },
] as const;

const DAY_MINUTES = 24 * 60;

export function shiftForMinutes(minutes: number): CafeShift {
  const wrapped = ((minutes % DAY_MINUTES) + DAY_MINUTES) % DAY_MINUTES;
  if (wrapped >= 6 * 60 && wrapped < 14 * 60) return 'morning';
  if (wrapped >= 14 * 60 && wrapped < 22 * 60) return 'day';
  return 'night';
}

export const BARISTA_IDS = ['barista_karin', 'barista_nadia', 'barista_ayu'] as const;
export type BaristaId = (typeof BARISTA_IDS)[number];

export type BaristaRoster = Record<CafeShift, BaristaId>;

/**
 * Pick a reproducible roster for a game day. Shuffling the three baristas
 * means the same day always has the same faces, while a new day rotates them.
 */
export function rosterForDay(day: number): BaristaRoster {
  const random = mulberry32((0x7e44a5 ^ Math.imul(day, 0x9e3779b1)) >>> 0);
  const pool: BaristaId[] = [...BARISTA_IDS];
  for (let index = pool.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(random() * (index + 1));
    [pool[index], pool[swap]] = [pool[swap]!, pool[index]!];
  }
  return { morning: pool[0]!, day: pool[1]!, night: pool[2]! };
}

export function baristaForMinutes(day: number, minutes: number): BaristaId {
  return rosterForDay(day)[shiftForMinutes(minutes)];
}

export interface ChairPoint {
  id: string;
  x: number;
  z: number;
  yaw: number;
}

export interface Point2 {
  x: number;
  z: number;
}

/** The chair closest to the counter is kept free for the player. */
export function pickReservedSeat(
  chairs: readonly ChairPoint[],
  orderPoint: Point2,
): ChairPoint | null {
  let best: ChairPoint | null = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const chair of chairs) {
    const distance = Math.hypot(chair.x - orderPoint.x, chair.z - orderPoint.z);
    if (distance < bestDistance) {
      best = chair;
      bestDistance = distance;
    }
  }
  return best;
}

/** Centre of the table a café chair belongs to, estimated from its neighbours. */
export function tableCentreFor(
  seat: ChairPoint,
  chairs: readonly ChairPoint[],
): Point2 {
  let x = 0;
  let z = 0;
  let count = 0;
  for (const chair of chairs) {
    if (Math.hypot(chair.x - seat.x, chair.z - seat.z) > 2.4) continue;
    x += chair.x;
    z += chair.z;
    count += 1;
  }
  if (count === 0) return { x: seat.x, z: seat.z };
  return { x: x / count, z: z / count };
}

/**
 * Stand one metre from the table, sixty degrees around from the diner's chair.
 * That keeps the barista out of both the chair and the tabletop.
 */
export function serveSpotFor(seat: ChairPoint, chairs: readonly ChairPoint[]): ChairPoint {
  const centre = tableCentreFor(seat, chairs);
  const angle = Math.atan2(seat.z - centre.z, seat.x - centre.x) + Math.PI / 3;
  const x = centre.x + Math.cos(angle) * 1.0;
  const z = centre.z + Math.sin(angle) * 1.0;
  const yaw = Math.atan2(-(seat.x - x), -(seat.z - z));
  return { id: `serve:${seat.id}`, x, z, yaw };
}

