import * as THREE from 'three';
import type { Npc } from './npc';
import { t } from '../i18n';
import { createServedCup } from '../render/drinks';
import type { LayoutSeat, TownLayout } from '../world/collision';
import {
  BARISTA_BREW,
  BARISTA_STAND,
  BAR_ENTRY_PATH,
  BAR_EXIT_PATH,
  CAFE_SHIFTS,
  CUSTOMER_ORDER,
  findCafeItem,
  pickReservedSeat,
  rosterForDay,
  serveSpotFor,
  shiftForMinutes,
  tableCentreFor,
  type BaristaId,
  type BaristaRoster,
  type CafeItemId,
  type CafeShift,
  type ChairPoint,
} from './cafeData';

export interface CafeHooks {
  onOpenMenu: (baristaName: string, shiftLabel: string) => void;
  onCloseMenu: () => void;
  onToast: (message: string) => void;
  onServed: () => void;
  onPlayerSay: (message: string) => void;
  /** The player's current seat id, so ambient guests never take it. */
  playerSeatId: () => string | null;
}

type OrderState =
  | 'toBrew'
  | 'brewing'
  | 'toBar'
  | 'awaitingSeat'
  | 'walkingToSeat'
  | 'serving'
  | 'returning'
  | 'walkingBack';

interface Order {
  itemId: CafeItemId;
  state: OrderState;
  timer: number;
  requestedSeat: ChairPoint | null;
  served: boolean;
}

type GuestState = 'toCounter' | 'ordering' | 'toSeat' | 'seated' | 'leaving';

interface GuestCycle {
  npc: Npc;
  state: GuestState;
  timer: number;
  seat: ChairPoint | null;
  home: { x: number; z: number; yaw: number };
}

interface CupHandle {
  group: THREE.Group;
  dispose: () => void;
}

const BREW_SECONDS = 5.0;
const SERVE_SECONDS = 1.7;
const RETURN_SECONDS = 2.4;
const GUEST_SEATED_SECONDS = 24;
const GUEST_FIRST_DELAY = 9;
const GUEST_COOLDOWN = 17;
const TERRACE_Y = 0.14;

export class Cafe {
  private readonly chairs: ChairPoint[];
  private readonly reserved: ChairPoint | null;
  private readonly baristas: Npc[];
  private readonly guests: Npc[];
  private readonly hooks: CafeHooks;
  private readonly scene: THREE.Scene;
  private readonly highlight: THREE.Mesh;
  private activeBarista: Npc | null = null;
  private roster: BaristaRoster | null = null;
  private rosterDay = -1;
  private day = 1;
  private shift: CafeShift | null = null;
  private pendingShift: CafeShift | null = null;
  private menuOpen = false;
  private order: Order | null = null;
  private servedSeat: ChairPoint | null = null;
  private carried: CupHandle | null = null;
  private tableCup: CupHandle | null = null;
  private pulse = 0;
  private guestCycle: GuestCycle | null = null;
  private guestIndex = -1;
  private guestCooldown = GUEST_FIRST_DELAY;

  constructor(scene: THREE.Scene, layout: TownLayout, npcs: Npc[], hooks: CafeHooks) {
    this.scene = scene;
    this.hooks = hooks;
    this.baristas = npcs.filter((npc) => npc.definition.role === 'barista');
    this.guests = npcs.filter((npc) => npc.definition.role === 'cafe_guest');

    const zone = layout.zones.find((entry) => entry.id === 'cafe');
    const counter = layout.interactables.find((entry) => entry.kind === 'cafe');
    const radius = zone?.r ?? 8;
    this.chairs = layout.seats
      .filter(
        (seat) =>
          seat.kind === 'chair' &&
          zone !== undefined &&
          Math.hypot(seat.x - zone.x, seat.z - zone.z) <= radius,
      )
      .map((seat) => ({ id: seat.id, x: seat.x, z: seat.z, yaw: seat.yaw }));
    this.reserved = counter ? pickReservedSeat(this.chairs, counter) : null;

    const ring = new THREE.RingGeometry(0.42, 0.56, 36);
    const material = new THREE.MeshBasicMaterial({
      color: 0xffd28a,
      transparent: true,
      opacity: 0.78,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.highlight = new THREE.Mesh(ring, material);
    this.highlight.rotation.x = -Math.PI / 2;
    this.highlight.visible = false;
    this.scene.add(this.highlight);

    for (const barista of this.baristas) {
      barista.setScripted(true);
      barista.setVisible(false);
    }

    // Warm bulbs under the authored pendant shades. Without these the black
    // container swallows the back bar, while the reference terrace reads as a
    // warm, lit cabin at any hour.
    for (const offset of [2.4, 1.0, -0.4]) {
      const lamp = new THREE.PointLight(0xffc98a, 7, 4.2, 2);
      lamp.position.set(BARISTA_STAND.x - 0.35, 2.28, BARISTA_STAND.z + offset);
      this.scene.add(lamp);
    }
  }

  get reservedSeat(): ChairPoint | null {
    return this.reserved;
  }

  get activeName(): string {
    return this.activeBarista
      ? t(`npc.${this.activeBarista.definition.id}.name`)
      : t('cafe.barista.fallback');
  }

  get isMenuOpen(): boolean {
    return this.menuOpen;
  }

  /** Reset all café state when a game starts or the calendar rolls over. */
  reset(day: number, minutes: number): void {
    this.closeMenu(true);
    this.clearOrder();
    this.clearTableCup();
    this.highlight.visible = false;
    this.day = day;
    this.shift = null;
    this.pendingShift = null;
    this.guestCooldown = GUEST_FIRST_DELAY;
    if (this.guestCycle) this.clearGuestCup(this.guestCycle);
    this.guestCycle = null;
    this.roster = null;
    this.rosterDay = -1;

    for (const guest of this.guests) {
      const definition = guest.definition;
      guest.setVisible(true);
      guest.setScripted(false);
      guest.teleportTo(definition.x, definition.z, definition.yaw);
    }

    this.refreshShift(shiftForMinutes(minutes));
  }

  update(dt: number, day: number, minutes: number): void {
    if (day !== this.day) {
      this.reset(day, minutes);
      return;
    }

    const shift = shiftForMinutes(minutes);
    if (shift !== this.shift) {
      if (this.canSwapBarista()) this.refreshShift(shift);
      else this.pendingShift = shift;
    }
    if (this.pendingShift && this.canSwapBarista()) {
      const next = this.pendingShift;
      this.pendingShift = null;
      this.refreshShift(next);
    }

    this.updateOrder(dt);
    this.updateGuests(dt);
    this.updateHighlight(dt);
  }

  openMenu(): boolean {
    if (this.menuOpen) return true;
    if (!this.activeBarista) return false;

    if (this.order) {
      if (this.order.state === 'awaitingSeat') {
        this.showSeatHint();
      } else {
        this.hooks.onToast(t('cafe.toast.busy'));
      }
      return true;
    }

    this.menuOpen = true;
    const shift = CAFE_SHIFTS.find((entry) => entry.id === this.shift);
    this.hooks.onOpenMenu(this.activeName, shift ? t(shift.labelKey) : '');
    this.activeBarista.character.say(t('cafe.barista.greeting'), 4.5);
    return true;
  }

  closeMenu(notify = true): void {
    if (!this.menuOpen) return;
    this.menuOpen = false;
    if (notify) this.hooks.onCloseMenu();
  }

  /** Explain a hovered drink through the barista's bubble. */
  describe(itemId: string): void {
    if (!this.menuOpen || !this.activeBarista) return;
    const item = findCafeItem(itemId);
    if (!item) return;
    this.activeBarista.character.say(t(item.descKey), 4.8);
  }

  /** Confirm the choice, then brew behind the counter. */
  orderItem(itemId: string): void {
    if (!this.menuOpen || !this.activeBarista) return;
    const item = findCafeItem(itemId);
    if (!item) return;

    this.menuOpen = false;
    this.hooks.onCloseMenu();
    this.clearTableCup();
    this.hooks.onToast(t('cafe.toast.brewing'));

    this.order = {
      itemId: item.id,
      state: 'toBrew',
      timer: 0,
      requestedSeat: null,
      served: false,
    };
    this.servedSeat = null;

    const barista = this.activeBarista;
    barista.character.say(t('cafe.confirm', { item: item.name }), 4.2);
    barista.walkPath([BARISTA_BREW], {
      ignoreCollision: true,
      onDone: () => {
        if (!this.order) return;
        this.order.state = 'brewing';
        this.order.timer = BREW_SECONDS;
        barista.character.playGesture('brew');
      },
    });
  }

  /** Called after the player settles into a chair. */
  onPlayerSeated(seat: LayoutSeat): void {
    if (seat.kind !== 'chair') return;
    const chair = this.chairs.find((entry) => entry.id === seat.id);
    if (!chair || !this.order) return;
    this.order.requestedSeat = chair;
    if (this.order.state === 'awaitingSeat') this.startServing(chair);
  }

  private canSwapBarista(): boolean {
    return !this.menuOpen && !this.order;
  }

  private currentRoster(): BaristaRoster {
    if (!this.roster || this.rosterDay !== this.day) {
      this.roster = rosterForDay(this.day);
      this.rosterDay = this.day;
    }
    return this.roster;
  }

  private refreshShift(shift: CafeShift): void {
    this.shift = shift;
    const selected: BaristaId = this.currentRoster()[shift];

    for (const barista of this.baristas) {
      const active = barista.definition.id === selected;
      barista.setScripted(true);
      barista.setVisible(active);
      if (active) {
        this.activeBarista = barista;
        barista.teleportTo(BARISTA_STAND.x, BARISTA_STAND.z, BARISTA_STAND.yaw);
      }
    }
  }

  private updateOrder(dt: number): void {
    const order = this.order;
    if (!order) {
      this.highlight.visible = false;
      return;
    }

    switch (order.state) {
      case 'brewing': {
        order.timer -= dt;
        if (order.timer <= 0) this.finishBrew();
        break;
      }
      case 'awaitingSeat': {
        if (order.requestedSeat) this.startServing(order.requestedSeat);
        break;
      }
      case 'serving': {
        order.timer -= dt;
        if (order.timer <= 0 && !order.served) this.placeCup();
        break;
      }
      case 'returning': {
        order.timer -= dt;
        if (order.timer <= 0) this.sendBaristaBack();
        break;
      }
      case 'toBrew':
      case 'toBar':
      case 'walkingToSeat':
      case 'walkingBack':
        break;
    }
  }

  private finishBrew(): void {
    const barista = this.activeBarista;
    const order = this.order;
    if (!barista || !order) return;
    order.state = 'toBar';
    this.carried = this.makeCup(order.itemId);
    barista.character.setCarried(this.carried.group);
    barista.walkPath([BARISTA_STAND], {
      ignoreCollision: true,
      onDone: () => {
        if (!this.order) return;
        this.order.state = 'awaitingSeat';
        this.hooks.onToast(t('cafe.toast.ready'));
        this.showSeatHint();
        if (this.order.requestedSeat) this.startServing(this.order.requestedSeat);
      },
    });
  }

  private showSeatHint(): void {
    if (!this.reserved) return;
    this.highlight.visible = true;
    this.highlight.position.set(this.reserved.x, TERRACE_Y, this.reserved.z);
  }

  private startServing(seat: ChairPoint): void {
    const order = this.order;
    const barista = this.activeBarista;
    if (!order || !barista) return;
    if (order.state === 'walkingToSeat' || order.state === 'serving') return;

    order.state = 'walkingToSeat';
    order.requestedSeat = seat;
    this.servedSeat = seat;
    this.highlight.visible = false;
    const spot = serveSpotFor(seat, this.chairs);
    barista.walkPath([...BAR_EXIT_PATH, spot], {
      ignoreCollision: true,
      onDone: () => {
        if (!this.order) return;
        this.order.state = 'serving';
        this.order.timer = SERVE_SECONDS;
        barista.faceTo(seat.x, seat.z);
        barista.character.playGesture('serve');
      },
    });
  }

  private placeCup(): void {
    const order = this.order;
    const barista = this.activeBarista;
    const seat = this.servedSeat;
    if (!order || !barista || !seat) return;

    order.served = true;
    order.state = 'returning';
    order.timer = RETURN_SECONDS;

    if (this.carried) {
      barista.character.setCarried(null);
      const centre = tableCentreFor(seat, this.chairs);
      // The table centre is occupied by the parasol pole, so set the cup on
      // the diner's side of the tabletop instead of inside the pole.
      const angle = Math.atan2(seat.z - centre.z, seat.x - centre.x);
      const cup = this.carried;
      cup.group.position.set(
        centre.x + Math.cos(angle) * 0.3,
        0.785,
        centre.z + Math.sin(angle) * 0.3,
      );
      cup.group.rotation.set(0, 0, 0);
      this.scene.add(cup.group);
      this.tableCup = cup;
      this.carried = null;
    }

    barista.character.say(t('cafe.enjoy'), 4.2);
    this.hooks.onPlayerSay(t('cafe.thanks'));
    this.hooks.onServed();
    this.hooks.onToast(t('cafe.toast.served'));
  }

  private sendBaristaBack(): void {
    const order = this.order;
    const barista = this.activeBarista;
    if (!order || !barista) return;
    order.state = 'walkingBack';
    barista.walkPath([...BAR_ENTRY_PATH, BARISTA_STAND], {
      ignoreCollision: true,
      onDone: () => {
        this.order = null;
        this.servedSeat = null;
      },
    });
  }

  private updateGuests(dt: number): void {
    const cycle = this.guestCycle;
    if (!cycle) {
      if (this.order || this.menuOpen) return;
      this.guestCooldown -= dt;
      if (this.guestCooldown <= 0) this.startGuestCycle();
      return;
    }

    switch (cycle.state) {
      case 'ordering': {
        cycle.timer -= dt;
        if (cycle.timer <= 0) this.sendGuestToSeat(cycle);
        break;
      }
      case 'seated': {
        cycle.timer -= dt;
        if (cycle.timer <= 0) this.sendGuestHome(cycle);
        break;
      }
      case 'toCounter':
      case 'toSeat':
      case 'leaving':
        break;
    }
  }

  private startGuestCycle(): void {
    if (this.guests.length === 0 || !this.reserved) return;
    const seat = this.findFreeChair();
    if (!seat) {
      this.guestCooldown = 7;
      return;
    }

    this.guestIndex = (this.guestIndex + 1) % this.guests.length;
    const npc = this.guests[this.guestIndex]!;
    const home = { x: npc.definition.x, z: npc.definition.z, yaw: npc.definition.yaw };
    const cycle: GuestCycle = { npc, state: 'toCounter', timer: 0, seat, home };
    this.guestCycle = cycle;
    npc.setVisible(true);
    npc.setScripted(true);

    npc.walkPath([{ x: 19.0, z: 16.1 }, CUSTOMER_ORDER], {
      ignoreCollision: true,
      onDone: () => {
        cycle.state = 'ordering';
        cycle.timer = 3.4;
        npc.faceTo(BARISTA_STAND.x, BARISTA_STAND.z);
      },
    });
  }

  private sendGuestToSeat(cycle: GuestCycle): void {
    const seat = cycle.seat;
    if (!seat) {
      this.sendGuestHome(cycle);
      return;
    }
    cycle.state = 'toSeat';
    cycle.npc.walkPath([{ x: seat.x, z: seat.z }], {
      ignoreCollision: true,
      onDone: () => {
        cycle.state = 'seated';
        cycle.timer = GUEST_SEATED_SECONDS;
        cycle.npc.sitAt(seat);
        this.placeGuestCup(cycle);
      },
    });
  }

  private sendGuestHome(cycle: GuestCycle): void {
    cycle.state = 'leaving';
    this.clearGuestCup(cycle);
    const seat = cycle.seat;
    const exit = seat ? { x: seat.x, z: seat.z } : { x: cycle.npc.x, z: cycle.npc.z };
    cycle.npc.standAt(exit.x, exit.z, cycle.npc.yaw);
    cycle.npc.walkPath([{ x: 19.0, z: 16.1 }, cycle.home], {
      ignoreCollision: true,
      onDone: () => {
        cycle.npc.teleportTo(cycle.home.x, cycle.home.z, cycle.home.yaw);
        cycle.npc.setScripted(false);
        this.guestCycle = null;
        this.guestCooldown = GUEST_COOLDOWN;
      },
    });
  }

  private findFreeChair(): ChairPoint | null {
    const playerSeat = this.hooks.playerSeatId();
    for (const chair of this.chairs) {
      if (chair.id === this.reserved?.id) continue;
      if (chair.id === playerSeat) continue;
      return chair;
    }
    return null;
  }

  private makeCup(itemId: CafeItemId): CupHandle {
    const group = createServedCup(itemId);
    const dispose = group.userData.dispose as (() => void) | undefined;
    return {
      group,
      dispose: () => {
        dispose?.();
        group.removeFromParent();
      },
    };
  }

  private placeGuestCup(cycle: GuestCycle): void {
    const seat = cycle.seat;
    if (!seat) return;
    this.clearGuestCup(cycle);
    const cup = this.makeCup('hot_latte');
    const centre = tableCentreFor(seat, this.chairs);
    const angle = Math.atan2(seat.z - centre.z, seat.x - centre.x) + Math.PI;
    cup.group.position.set(
      centre.x + Math.cos(angle) * 0.22,
      0.785,
      centre.z + Math.sin(angle) * 0.22,
    );
    this.scene.add(cup.group);
    cycle.npc.character.container.userData.guestCup = cup;
  }

  private clearGuestCup(cycle: GuestCycle): void {
    const cup = cycle.npc.character.container.userData.guestCup as CupHandle | undefined;
    if (!cup) return;
    cup.dispose();
    delete cycle.npc.character.container.userData.guestCup;
  }

  private updateHighlight(dt: number): void {
    if (!this.highlight.visible) return;
    this.pulse += dt;
    const scale = 1 + Math.sin(this.pulse * 3.2) * 0.08;
    this.highlight.scale.setScalar(scale);
    const material = this.highlight.material as THREE.MeshBasicMaterial;
    material.opacity = 0.58 + Math.sin(this.pulse * 3.2) * 0.18;
  }

  private clearOrder(): void {
    this.order = null;
    this.servedSeat = null;
    this.highlight.visible = false;
    if (this.carried) {
      this.activeBarista?.character.setCarried(null);
      this.carried.dispose();
      this.carried = null;
    }
  }

  private clearTableCup(): void {
    this.tableCup?.dispose();
    this.tableCup = null;
  }
}
