import * as THREE from 'three';
import { applyCurvedWorld, type CurveUniforms } from './curved';
import {
  applyFoamMotion,
  applySeaMotion,
  applyWindSway,
  getWind,
  isWindMaterial,
} from './wind';
import {
  cafeHoursTexture,
  cafeMenuTexture,
  cafeNameTexture,
  cobbleTexture,
  fabricTexture,
  foamTexture,
  grassTexture,
  laMarzukiTexture,
  palmBarkTexture,
  plasterTexture,
  roofTexture,
  sandTexture,
  seaTexture,
  stoneTexture,
  woodTexture,
} from './textures';

interface Spec {
  color: number;
  roughness?: number;
  metalness?: number;
  map?: THREE.Texture;
  emissive?: number;
  emissiveIntensity?: number;
  transparent?: boolean;
  opacity?: number;
}

export interface MaterialSet {
  town: Map<string, THREE.MeshStandardMaterial>;
  glow: Array<{ material: THREE.MeshStandardMaterial; intensity: number }>;
  dispose(): void;
}

/**
 * The GLB carries material names only; the look is authored here so the
 * palette in docs/art-bible.md stays the single source of truth.
 */
export function createTownMaterials(curve: CurveUniforms): MaterialSet {
  const stone = stoneTexture();
  const cobble = cobbleTexture();
  const plaster = plasterTexture();
  const roof = roofTexture();
  const wood = woodTexture();
  const grass = grassTexture();
  const fabric = fabricTexture();
  const sand = sandTexture();
  const palmBark = palmBarkTexture();
  const sea = seaTexture();
  const foam = foamTexture();
  const cafeName = cafeNameTexture();
  const cafeMenu = cafeMenuTexture();
  const cafeHours = cafeHoursTexture();
  const laMarzuki = laMarzukiTexture();

  const specs: Record<string, Spec> = {
    MAT_Grass: { color: 0x5d7042, map: grass, roughness: 0.98 },
    MAT_Grass_Dark: { color: 0x46583a, map: grass, roughness: 0.98 },
    MAT_Cobble: { color: 0x9b988e, map: cobble, roughness: 0.96 },
    MAT_Cobble_Plaza: { color: 0xb0aca1, map: cobble, roughness: 0.94 },
    MAT_Cobble_Dark: { color: 0x858078, map: cobble, roughness: 0.97 },
    MAT_Stone: { color: 0xc3bcae, map: stone, roughness: 0.94 },
    MAT_Stone_Light: { color: 0xd6cfc1, map: stone, roughness: 0.92 },
    MAT_Stone_Dark: { color: 0x9e988c, map: stone, roughness: 0.96 },
    MAT_Plaster_Cream: { color: 0xe8e1d3, map: plaster, roughness: 0.93 },
    MAT_Plaster_Warm: { color: 0xd8c9b4, map: plaster, roughness: 0.93 },
    MAT_Plaster_White: { color: 0xf0ece2, map: plaster, roughness: 0.92 },
    MAT_Plaster_Yellow: { color: 0xe2cf9d, map: plaster, roughness: 0.93 },
    MAT_Plaster_Rose: { color: 0xcba99b, map: plaster, roughness: 0.93 },
    MAT_Timber_Dark: { color: 0x40332a, map: wood, roughness: 0.9 },
    MAT_Timber_Warm: { color: 0x6a4a35, map: wood, roughness: 0.9 },
    MAT_Roof_Tile: { color: 0xb05f45, map: roof, roughness: 0.88 },
    MAT_Roof_Tile_Dark: { color: 0x7e3f30, map: roof, roughness: 0.9 },
    MAT_Roof_Slate: { color: 0x555a5c, map: roof, roughness: 0.86 },
    MAT_Wood: { color: 0x6b4a30, map: wood, roughness: 0.9 },
    MAT_Wood_Light: { color: 0x96754a, map: wood, roughness: 0.88 },
    MAT_Metal: { color: 0x3a3d3b, roughness: 0.55, metalness: 0.55 },
    MAT_Glass: {
      color: 0x2f3b40,
      roughness: 0.22,
      metalness: 0.1,
      emissive: 0xffb166,
      emissiveIntensity: 0,
    },
    MAT_Lantern: {
      color: 0xf0c07a,
      roughness: 0.4,
      emissive: 0xffa13e,
      emissiveIntensity: 1.6,
    },
    MAT_Water: { color: 0x3f6266, roughness: 0.12, metalness: 0.05 },
    MAT_Foliage: { color: 0x6b7f4c, roughness: 0.95 },
    MAT_Foliage_Dark: { color: 0x51663f, roughness: 0.96 },
    MAT_Trunk: { color: 0x5b4530, map: wood, roughness: 0.97 },
    MAT_Flower_Red: { color: 0xa8423a, roughness: 0.88 },
    MAT_Flower_Pink: { color: 0xc9868f, roughness: 0.88 },
    MAT_Flower_White: { color: 0xe6dccb, roughness: 0.88 },
    MAT_Fabric_Cream: { color: 0xded2bb, map: fabric, roughness: 0.96 },
    MAT_Fabric_Green: { color: 0x647454, map: fabric, roughness: 0.96 },
    MAT_Fabric_Red: { color: 0x9a5548, map: fabric, roughness: 0.96 },
    MAT_Brick: { color: 0x8a5347, map: stone, roughness: 0.94 },
    MAT_Flag: { color: 0x8d4038, map: fabric, roughness: 0.92 },
    // Coast and grove. Sand stays pale and dry; the wet band is darker and
    // glossier. Water is deliberately smooth so the low sun leaves glints.
    MAT_Sand: { color: 0xe0d1ac, map: sand, roughness: 0.97 },
    MAT_Sand_Wet: { color: 0xb3a284, map: sand, roughness: 0.55, metalness: 0.05 },
    MAT_Sea: { color: 0x2f7d8c, map: sea, roughness: 0.16, metalness: 0.12 },
    MAT_Sea_Shallow: { color: 0x5fadae, map: sea, roughness: 0.22, metalness: 0.06 },
    MAT_Foam: { color: 0xeaf1e8, map: foam, roughness: 0.62, transparent: true, opacity: 0.92 },
    MAT_Rock: { color: 0x979187, map: stone, roughness: 0.97 },
    MAT_Dirt: { color: 0x937250, map: sand, roughness: 0.98 },
    MAT_Palm_Trunk: { color: 0x94784f, map: palmBark, roughness: 0.96 },
    MAT_Palm_Leaf: { color: 0x6f8c48, map: grass, roughness: 0.94 },
    MAT_Palm_Leaf_Dark: { color: 0x506b38, map: grass, roughness: 0.95 },
    MAT_Palm_Fruit: { color: 0xa9672c, roughness: 0.86 },
    MAT_Cushion: { color: 0xe3dbc6, map: fabric, roughness: 0.95 },
    MAT_Teak: { color: 0x8b6539, map: wood, roughness: 0.9 },
    // TerrasKastil. keeps the reference's black container shell, oak deck and
    // counter, white stools, and warm chrome fittings.
    MAT_Container: { color: 0x20261f, roughness: 0.62, metalness: 0.24 },
    MAT_Container_Rib: { color: 0x151a16, roughness: 0.56, metalness: 0.3 },
    MAT_Counter_Wood: { color: 0xa97544, map: wood, roughness: 0.82 },
    MAT_Stool: { color: 0xece6da, roughness: 0.42, metalness: 0.16 },
    MAT_Chrome: { color: 0xc7cec9, roughness: 0.24, metalness: 0.92 },
    MAT_Ceramic: { color: 0xf1e8d9, roughness: 0.42 },
    MAT_Espresso_Cream: { color: 0xceb392, roughness: 0.5 },
    MAT_Awning: { color: 0x303a32, map: fabric, roughness: 0.9 },
    // Sign quads carry their own painted map. A whisper of emissive keeps the
    // menu readable after sunset without turning the plate into a lamp.
    MAT_Sign_Cafe: {
      color: 0xffffff,
      map: cafeName,
      roughness: 0.58,
      emissive: 0x241f16,
      emissiveIntensity: 0.65,
    },
    MAT_Sign_Menu: {
      color: 0xffffff,
      map: cafeMenu,
      roughness: 0.7,
      emissive: 0x1b211c,
      emissiveIntensity: 0.55,
    },
    MAT_Sign_Hours: {
      color: 0xffffff,
      map: cafeHours,
      roughness: 0.62,
      emissive: 0x241f16,
      emissiveIntensity: 0.6,
    },
    MAT_Sign_LaMarzuki: {
      color: 0xffffff,
      map: laMarzuki,
      roughness: 0.34,
      metalness: 0.35,
      emissive: 0x232825,
      emissiveIntensity: 0.5,
    },
  };

  const town = new Map<string, THREE.MeshStandardMaterial>();
  const glow: MaterialSet['glow'] = [];

  for (const [name, spec] of Object.entries(specs)) {
    const material = new THREE.MeshStandardMaterial({
      color: spec.color,
      roughness: spec.roughness ?? 0.9,
      metalness: spec.metalness ?? 0,
      map: spec.map ?? null,
      transparent: spec.transparent ?? false,
      opacity: spec.opacity ?? 1,
      side: THREE.FrontSide,
    });
    material.name = name;
    if (spec.emissive !== undefined) {
      material.emissive = new THREE.Color(spec.emissive);
      material.emissiveIntensity = spec.emissiveIntensity ?? 1;
      glow.push({ material, intensity: spec.emissiveIntensity ?? 1 });
    }
    applyCurvedWorld(material, curve);
    // Animate only the materials whose base geometry is authored for it. The
    // curve patch stays first so the wind displacement is bent with the world.
    if (isWindMaterial(name)) applyWindSway(material);
    else if (name === 'MAT_Sea' || name === 'MAT_Sea_Shallow') applySeaMotion(material);
    else if (name === 'MAT_Foam') applyFoamMotion(material);
    town.set(name, material);
  }

  return {
    town,
    glow,
    dispose() {
      for (const material of town.values()) material.dispose();
      town.clear();
    },
  };
}

/** Glass and street lamps pick up a warm interior light in the late afternoon. */
export function setWindowGlow(materials: MaterialSet, amount: number): void {
  for (const entry of materials.glow) {
    const isLantern = entry.material.name === 'MAT_Lantern';
    entry.material.emissiveIntensity = isLantern
      ? amount * 2.2
      : amount * 1.15;
  }
}

/**
 * Drift the sea and foam textures with the wind. Both use the shared wind
 * clock, so the pattern travels in the same direction as the leaf sway and the
 * slow vertex ripples in the shader.
 */
export function animateWater(materials: MaterialSet): void {
  const wind = getWind();
  const sea = materials.town.get('MAT_Sea');
  if (sea?.map) {
    // Both water materials share the same cached texture, so one offset is
    // enough and avoids uploading the canvas again every frame.
    sea.map.offset.set(
      wind.time * 0.006 * wind.x * wind.strength,
      wind.time * 0.014 * wind.z * wind.strength,
    );
  }
  const foam = materials.town.get('MAT_Foam');
  if (foam?.map) {
    // Foam drifts faster than the deep water because it sits at the shoreline.
    foam.map.offset.set(wind.time * 0.018, wind.time * 0.05 * wind.z);
  }
}
