export const SAVE_VERSION = 1;

export interface SaveData {
  version: number;
  characterId: string;
  day: number;
  time: number;
  activities: Record<string, boolean>;
  position: { x: number; z: number };
  savedAt: number;
}

const STORAGE_KEY = 'dailylife.save.v1';

export function createSave(
  characterId: string,
  day: number,
  time: number,
  activities: Record<string, boolean>,
  position: { x: number; z: number },
): SaveData {
  return {
    version: SAVE_VERSION,
    characterId,
    day,
    time,
    activities: { ...activities },
    position: { ...position },
    savedAt: Date.now(),
  };
}

export function loadSave(): SaveData | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw) as Partial<SaveData>;
    if (data.version !== SAVE_VERSION || typeof data.characterId !== 'string') return null;
    if (typeof data.day !== 'number' || typeof data.time !== 'number') return null;
    const activities: Record<string, boolean> = {};
    if (data.activities && typeof data.activities === 'object') {
      for (const [key, value] of Object.entries(data.activities)) {
        if (typeof value === 'boolean') activities[key] = value;
      }
    }
    const pos = data.position;
    return {
      version: SAVE_VERSION,
      characterId: data.characterId,
      day: Math.max(1, Math.floor(data.day)),
      time: clampTime(data.time),
      activities,
      position:
        pos && typeof pos.x === 'number' && typeof pos.z === 'number'
          ? { x: pos.x, z: pos.z }
          : { x: 0, z: 28 },
      savedAt: typeof data.savedAt === 'number' ? data.savedAt : 0,
    };
  } catch {
    return null;
  }
}

export function writeSave(data: SaveData): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch {
    // Saving is a convenience; never let a storage quota error stop play.
  }
}

export function clearSave(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Ignore.
  }
}

export function clampTime(time: number): number {
  if (!Number.isFinite(time)) return 8 * 60;
  return Math.min(23 * 60 + 59, Math.max(0, time));
}
