import * as THREE from 'three';
import { clamp, damp, dampAngle } from '../core/math';
import { Character } from '../characters/character';
import type { CollisionWorld, LayoutSeat } from '../world/collision';

const WALK_SPEED = 2.7;
const RUN_SPEED = 5.2;
const RADIUS = 0.34;
const GRAVITY = 17;
const JUMP_SPEED = 5.1;
const MAX_WATER_DEPTH = 1.05;

export interface PlayerStep {
  onFootstep?: (running: boolean) => void;
}

export class Player {
  readonly character: Character;
  readonly position = new THREE.Vector3();
  readonly velocity = new THREE.Vector3();
  yaw = 0;
  grounded = true;
  blocked = false;
  seatId: string | null = null;
  lying = false;
  waterDepth = 0;

  private verticalVelocity = 0;
  private stepAccumulator = 0;
  private waterTime = 0;
  private wrapped = false;

  constructor(
    character: Character,
    private readonly collision: CollisionWorld,
    spawn: { x: number; z: number },
  ) {
    this.character = character;
    this.position.set(spawn.x, collision.groundAt(spawn.x, spawn.z, 0), spawn.z);
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
  }

  get seated(): boolean {
    return this.seatId !== null;
  }

  teleport(x: number, z: number, yaw = this.yaw): void {
    this.seatId = null;
    this.lying = false;
    this.character.setSeated(false);
    this.character.setLounging(false);
    this.position.set(x, this.collision.groundAt(x, z), z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.waterDepth = 0;
    this.waterTime = 0;
    this.yaw = yaw;
    this.character.setPosition(x, this.position.y, z);
    this.character.setYaw(yaw);
  }

  /** Settle into a chair or bench without walking there. */
  sit(seat: LayoutSeat): void {
    this.seatId = seat.id;
    this.lying = false;
    this.position.set(seat.x, this.collision.groundAt(seat.x, seat.z, this.position.y), seat.z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.waterDepth = 0;
    this.yaw = seat.yaw;
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(seat.yaw);
    this.character.setSeated(true);
    this.character.setLounging(false);
  }

  /** Recline on a sun lounger while keeping the seat and its facing. */
  lieDown(): void {
    if (!this.seatId) return;
    this.lying = true;
    this.character.setLounging(true);
  }

  /** Return to an upright seated pose on the same lounger. */
  sitUp(): void {
    this.lying = false;
    this.character.setLounging(false);
  }

  /** Stand up just behind the seat and resolve any overlap with the furniture. */
  stand(): void {
    if (!this.seatId) return;
    const backX = Math.sin(this.yaw);
    const backZ = Math.cos(this.yaw);
    const targetX = this.position.x + backX * 0.95;
    const targetZ = this.position.z + backZ * 0.95;
    const resolved = this.collision.resolve(targetX, targetZ, RADIUS, this.position.y);
    this.seatId = null;
    this.lying = false;
    this.character.setSeated(false);
    this.character.setLounging(false);
    this.position.set(resolved.x, this.collision.groundAt(resolved.x, resolved.z, this.position.y), resolved.z);
    this.velocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
    this.waterDepth = 0;
    this.character.setPosition(this.position.x, this.position.y, this.position.z);
    this.character.setYaw(this.yaw);
  }

  update(dt: number, moveX: number, moveZ: number, running: boolean, jump: boolean, step: PlayerStep = {}): void {
    if (this.seated) {
      this.velocity.set(0, 0, 0);
      this.waterDepth = 0;
      this.character.update(dt, { speed: 0, airborne: false });
      return;
    }

    const length = Math.hypot(moveX, moveZ);
    // Wading slows the stride down without changing the input direction, and
    // the character sinks visually into the flat water plane.
    const depth = this.collision.waterDepthAt(this.position.x, this.position.z);
    const waterScale = 1 - clamp(depth / MAX_WATER_DEPTH, 0, 1) * 0.58;
    const speed = (running ? RUN_SPEED : WALK_SPEED) * waterScale;
    const targetX = length > 0.001 ? (moveX / length) * speed : 0;
    const targetZ = length > 0.001 ? (moveZ / length) * speed : 0;

    this.velocity.x = damp(this.velocity.x, targetX, this.grounded ? 14 : 4, dt);
    this.velocity.z = damp(this.velocity.z, targetZ, this.grounded ? 14 : 4, dt);

    if (length > 0.08) {
      const desiredYaw = Math.atan2(-moveX, -moveZ);
      this.yaw = dampAngle(this.yaw, desiredYaw, 11, dt);
    }

    if (jump && this.grounded && depth < 0.35) {
      this.verticalVelocity = JUMP_SPEED;
      this.grounded = false;
    }

    this.verticalVelocity -= GRAVITY * dt;
    let nextY = this.position.y + this.verticalVelocity * dt;

    const resolved = this.collision.resolve(
      this.position.x + this.velocity.x * dt,
      this.position.z + this.velocity.z * dt,
      RADIUS,
      this.position.y,
    );
    this.blocked = resolved.blocked;
    this.wrapped = resolved.wrapped;
    this.position.x = resolved.x;
    this.position.z = resolved.z;

    const ground = this.collision.groundAt(this.position.x, this.position.z, Math.max(this.position.y, nextY));
    if (nextY <= ground + 0.001 && this.verticalVelocity <= 0) {
      // Walking up the castle stair produces a smooth ramp, so snapping is
      // safe here; the small threshold avoids stepping through the platform.
      if (ground - nextY < 0.65 || this.position.y < ground) {
        nextY = ground;
      }
      this.verticalVelocity = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }

    if (nextY < ground) nextY = ground;
    this.position.y = nextY;

    this.waterDepth = damp(
      this.waterDepth,
      this.collision.waterDepthAt(this.position.x, this.position.z),
      4,
      dt,
    );
    this.waterTime += dt;
    const bob = Math.sin(this.waterTime * 1.8) * 0.035 * clamp(this.waterDepth / 0.5, 0, 1);

    const speedNow = Math.hypot(this.velocity.x, this.velocity.z);
    this.character.setPosition(
      this.position.x,
      this.position.y - this.waterDepth * 0.82 + bob,
      this.position.z,
    );
    this.character.setYaw(this.yaw);
    this.character.update(dt, { speed: speedNow, airborne: !this.grounded });

    this.stepAccumulator += speedNow * dt;
    if (this.stepAccumulator > 1.95) {
      this.stepAccumulator = 0;
      step.onFootstep?.(speedNow > WALK_SPEED + 0.4);
    }
  }

  /** Read and clear the one-frame wrap flag so the camera can snap after it. */
  consumeWrapped(): boolean {
    if (!this.wrapped) return false;
    this.wrapped = false;
    return true;
  }

  get inWater(): boolean {
    return this.waterDepth > 0.02;
  }

  get isLying(): boolean {
    return this.lying;
  }

  get speed(): number {
    return Math.hypot(this.velocity.x, this.velocity.z);
  }
}
