import * as THREE from 'three';
import type { CafeItemId } from '../gameplay/cafeData';

/**
 * Procedural drinks for the menu preview and the cups left on cafe tables.
 * Building them here keeps the silhouette, colours, and scale consistent
 * between the popup and the world.
 */
export interface DrinkModel {
  group: THREE.Group;
  /** Disposal is explicit because these are one-off menu models. */
  dispose(): void;
}

const CERAMIC = 0xf1e7d5;
const SAUCER = 0xe8ddc9;
const MATCHA = 0x7fa84a;
const MATCHA_DARK = 0x5f8a3b;
const ESPRESSO = 0x9a6234;
const CREAM = 0xf7eedc;
const GLASS = 0xdfeef0;

function standard(color: number, roughness = 0.5, metalness = 0): THREE.MeshStandardMaterial {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness });
}

/** A chalk-white rosetta drawn on a transparent canvas. */
function latteArtTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is unavailable');
  ctx.clearRect(0, 0, 128, 128);
  ctx.translate(64, 64);
  ctx.fillStyle = 'rgba(250, 244, 228, 0.96)';
  ctx.beginPath();
  ctx.ellipse(0, 30, 5, 16, 0, 0, Math.PI * 2);
  ctx.fill();
  for (let index = 0; index < 6; index += 1) {
    const spread = 0.55 - index * 0.07;
    const y = 20 - index * 12;
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(side * (7 + index * 2.4), y, 4 + spread * 5, 14 - index * 1.2, side * 0.55, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.beginPath();
  ctx.moveTo(0, -34);
  ctx.quadraticCurveTo(4, -14, 0, 4);
  ctx.quadraticCurveTo(-4, -14, 0, -34);
  ctx.fill();
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function addSaucer(group: THREE.Group, radius: number): THREE.Mesh[] {
  const saucer = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius * 0.94, 0.012, 32),
    standard(SAUCER, 0.42),
  );
  saucer.position.y = 0.006;
  group.add(saucer);
  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(radius * 0.72, 0.004, 6, 32),
    standard(0xded0b8, 0.5),
  );
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.014;
  group.add(rim);
  return [saucer, rim];
}

function addHandle(group: THREE.Group, x: number, y: number, radius: number): THREE.Mesh {
  const handle = new THREE.Mesh(
    new THREE.TorusGeometry(radius, radius * 0.28, 8, 18, Math.PI * 1.35),
    standard(CERAMIC, 0.4),
  );
  handle.rotation.z = -Math.PI * 0.16;
  handle.position.set(x, y, 0);
  group.add(handle);
  return handle;
}

function addLatteArt(group: THREE.Group, y: number, radius: number): THREE.Mesh {
  const texture = latteArtTexture();
  const art = new THREE.Mesh(
    new THREE.CircleGeometry(radius, 32),
    new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
  );
  art.rotation.x = -Math.PI / 2;
  art.position.y = y;
  group.add(art);
  return art;
}

function hotCup(liquid: number, art: boolean): THREE.Group {
  const group = new THREE.Group();
  const parts: THREE.Mesh[] = [];
  parts.push(...addSaucer(group, 0.135));

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.085, 0.062, 0.115, 28),
    standard(CERAMIC, 0.36),
  );
  body.position.y = 0.074;
  group.add(body);
  parts.push(body);

  const lip = new THREE.Mesh(
    new THREE.TorusGeometry(0.085, 0.005, 8, 28),
    standard(CERAMIC, 0.4),
  );
  lip.rotation.x = Math.PI / 2;
  lip.position.y = 0.132;
  group.add(lip);
  parts.push(lip);

  parts.push(addHandle(group, 0.088, 0.082, 0.035));

  const surface = new THREE.Mesh(
    new THREE.CylinderGeometry(0.078, 0.078, 0.008, 28),
    standard(liquid, liquid === MATCHA ? 0.32 : 0.2),
  );
  surface.position.y = 0.128;
  group.add(surface);
  parts.push(surface);

  if (art) addLatteArt(group, 0.1335, 0.068);

  group.userData.parts = parts;
  return group;
}

function icedMatcha(): THREE.Group {
  const group = new THREE.Group();
  const parts: THREE.Mesh[] = [];

  const coaster = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.075, 0.009, 28),
    standard(0x3c443d, 0.7),
  );
  coaster.position.y = 0.0045;
  group.add(coaster);
  parts.push(coaster);

  const glassMaterial = new THREE.MeshStandardMaterial({
    color: GLASS,
    roughness: 0.08,
    metalness: 0.02,
    transparent: true,
    opacity: 0.32,
  });
  const glass = new THREE.Mesh(new THREE.CylinderGeometry(0.058, 0.05, 0.2, 24, 1, true), glassMaterial);
  glass.position.y = 0.11;
  glass.material.side = THREE.DoubleSide;
  group.add(glass);
  parts.push(glass);

  const bottom = new THREE.Mesh(
    new THREE.CylinderGeometry(0.05, 0.05, 0.006, 24),
    glassMaterial,
  );
  bottom.position.y = 0.012;
  group.add(bottom);

  const matcha = new THREE.Mesh(
    new THREE.CylinderGeometry(0.053, 0.047, 0.13, 24),
    standard(MATCHA_DARK, 0.45),
  );
  matcha.position.y = 0.077;
  group.add(matcha);
  parts.push(matcha);

  const milk = new THREE.Mesh(
    new THREE.CylinderGeometry(0.052, 0.052, 0.036, 24),
    new THREE.MeshStandardMaterial({
      color: 0xe9f2cf,
      roughness: 0.6,
      transparent: true,
      opacity: 0.72,
    }),
  );
  milk.position.y = 0.158;
  group.add(milk);
  parts.push(milk);

  // A few cubes break up the cylinder and read as ice through the glass.
  const iceMaterial = new THREE.MeshStandardMaterial({
    color: 0xe8f5f6,
    roughness: 0.15,
    transparent: true,
    opacity: 0.5,
  });
  for (const [x, z, y, rot] of [
    [0.018, 0.012, 0.12, 0.4],
    [-0.02, -0.012, 0.145, -0.2],
    [0.005, -0.024, 0.1, 0.9],
  ] as const) {
    const cube = new THREE.Mesh(new THREE.BoxGeometry(0.032, 0.032, 0.032), iceMaterial);
    cube.position.set(x, y, z);
    cube.rotation.set(rot, rot * 1.7, rot * 0.6);
    group.add(cube);
    parts.push(cube);
  }

  const straw = new THREE.Mesh(
    new THREE.CylinderGeometry(0.006, 0.006, 0.24, 10),
    standard(0xd9b483, 0.35),
  );
  straw.position.set(-0.022, 0.19, 0.01);
  straw.rotation.z = 0.16;
  group.add(straw);
  parts.push(straw);

  group.userData.parts = parts;
  return group;
}

export function createDrink(id: CafeItemId): DrinkModel {
  const group =
    id === 'hot_latte'
      ? hotCup(ESPRESSO, true)
      : id === 'hot_matcha_latte'
        ? hotCup(MATCHA, true)
        : icedMatcha();

  const materials = new Set<THREE.Material>();
  const geometries = new Set<THREE.BufferGeometry>();
  group.traverse((object) => {
    if (!(object instanceof THREE.Mesh)) return;
    geometries.add(object.geometry);
    const list = Array.isArray(object.material) ? object.material : [object.material];
    for (const material of list) materials.add(material);
  });

  return {
    group,
    dispose() {
      for (const geometry of geometries) geometry.dispose();
      for (const material of materials) {
        if (material instanceof THREE.MeshBasicMaterial && material.map) material.map.dispose();
        material.dispose();
      }
      group.removeFromParent();
    },
  };
}

/** A smaller cup for a character's hand or a table. */
export function createServedCup(id: CafeItemId): THREE.Group {
  const model = createDrink(id);
  model.group.scale.setScalar(0.72);
  model.group.userData.dispose = model.dispose;
  return model.group;
}
