import { Character } from '../characters/character';
import { dampAngle, mulberry32 } from '../core/math';
import type { CollisionWorld, LayoutNpc } from '../world/collision';

interface PathPoint {
  x: number;
  z: number;
}

export interface PathOptions {
  /** Cafe staff paths cross the enclosed bar, so they skip the collider pass. */
  ignoreCollision?: boolean;
  onDone?: () => void;
}

export class Npc {
  readonly character: Character;
  readonly definition: LayoutNpc;
  private readonly homeX: number;
  private readonly homeZ: number;
  private readonly random: () => number;
  private readonly canGreet: boolean;
  private targetX: number;
  private targetZ: number;
  private pauseTimer: number;
  private walkTimer = 0;
  private moving = false;
  private speed = 0;
  private greetTimer: number;
  private scripted = false;
  private path: PathPoint[] = [];
  private pathDone: (() => void) | null = null;
  private ignoreCollision = false;
  private visible = true;
  talking = false;

  constructor(definition: LayoutNpc, character: Character, private readonly collision: CollisionWorld, seed: number) {
    this.definition = definition;
    this.character = character;
    this.homeX = definition.x;
    this.homeZ = definition.z;
    this.targetX = definition.x;
    this.targetZ = definition.z;
    this.random = mulberry32(seed * 7919 + 13);
    this.pauseTimer = 1 + this.random() * 4;
    this.greetTimer = 5 + this.random() * 9;
    this.canGreet = definition.role !== 'barista' && definition.role !== 'cafe_guest';
    this.character.setPosition(definition.x, collision.groundAt(definition.x, definition.z, 0), definition.z);
    this.character.setYaw(definition.yaw);
  }

  greet(kind: 'wave' | 'hello' = 'wave', message?: string): void {
    this.character.greet(kind);
    if (message) this.character.say(message);
  }

  get x(): number {
    return this.character.container.position.x;
  }

  get z(): number {
    return this.character.container.position.z;
  }

  get isScripted(): boolean {
    return this.scripted;
  }

  get yaw(): number {
    return this.character.container.rotation.y;
  }

  setVisible(visible: boolean): void {
    this.visible = visible;
    this.character.setVisible(visible);
  }

  /** Turn off wandering and auto-greeting so a controller can drive the NPC. */
  setScripted(scripted: boolean): void {
    this.scripted = scripted;
    if (!scripted) this.path = [];
    this.speed = 0;
    this.moving = false;
  }

  teleportTo(x: number, z: number, yaw: number): void {
    this.character.setSeated(false);
    this.character.setLounging(false);
    const y = this.collision.groundAt(x, z, 0);
    this.character.setPosition(x, y, z);
    this.character.setYaw(yaw);
    this.speed = 0;
    this.path = [];
    this.pathDone = null;
  }

  /** Follow a list of points, then optionally run a continuation. */
  walkPath(points: readonly PathPoint[], options: PathOptions = {}): void {
    this.scripted = true;
    this.path = points.map((point) => ({ x: point.x, z: point.z }));
    this.ignoreCollision = options.ignoreCollision ?? false;
    this.pathDone = options.onDone ?? null;
    this.speed = 0;
    this.moving = false;
  }

  /** Sit down without walking. Used after a path reaches a chair. */
  sitAt(seat: { x: number; z: number; yaw: number }): void {
    this.character.setSeated(false);
    const y = this.collision.groundAt(seat.x, seat.z, 0);
    this.character.setPosition(seat.x, y, seat.z);
    this.character.setYaw(seat.yaw);
    this.character.setSeated(true);
    this.character.setLounging(false);
    this.path = [];
    this.pathDone = null;
    this.speed = 0;
  }

  /** Stand up at an explicit spot, keeping the facing intact. */
  standAt(x: number, z: number, yaw: number): void {
    this.character.setSeated(false);
    const y = this.collision.groundAt(x, z, 0);
    this.character.setPosition(x, y, z);
    this.character.setYaw(yaw);
    this.path = [];
    this.pathDone = null;
    this.speed = 0;
  }

  /** Face a point immediately, without a frame of interpolation. */
  faceTo(x: number, z: number): void {
    this.character.setYaw(Math.atan2(-(x - this.x), -(z - this.z)));
  }

  update(dt: number, playerX: number, playerZ: number, greeting = ''): boolean {
    if (!this.visible) {
      this.speed = 0;
      this.character.update(dt, { speed: 0, airborne: false });
      return false;
    }

    if (this.scripted) {
      this.followPath(dt);
      this.character.update(dt, { speed: this.speed, airborne: false });
      return false;
    }

    const distance = Math.hypot(playerX - this.x, playerZ - this.z);
    const engaged = this.talking || distance < 3.6;
    this.greetTimer -= dt;
    let greeted = false;

    if (engaged) {
      this.speed = 0;
      this.character.faceTowards(playerX - this.x, playerZ - this.z, dt, 6);
      // A neighbour looks up and waves when you come close, then gets back to
      // their day for a while.
      if (!this.talking && this.canGreet && distance < 3.2 && this.greetTimer <= 0) {
        this.character.greet('wave');
        if (greeting) this.character.say(greeting);
        this.greetTimer = 14 + this.random() * 12;
        greeted = true;
      }
    } else if (!this.definition.idle) {
      this.wander(dt);
    } else {
      this.speed = 0;
      this.character.setYaw(
        dampAngle(this.character.container.rotation.y, this.definition.yaw, 2, dt),
      );
    }

    this.character.update(dt, { speed: this.speed, airborne: false });
    return greeted;
  }

  private followPath(dt: number): void {
    if (this.path.length === 0) {
      this.speed = 0;
      return;
    }

    const target = this.path[0]!;
    const dx = target.x - this.x;
    const dz = target.z - this.z;
    const distance = Math.hypot(dx, dz);
    if (distance < 0.14) {
      this.path.shift();
      if (this.path.length === 0) {
        this.speed = 0;
        const done = this.pathDone;
        this.pathDone = null;
        done?.();
      }
      return;
    }

    const step = Math.min(distance, 0.95 * dt);
    let nx = this.x + (dx / distance) * step;
    let nz = this.z + (dz / distance) * step;
    if (!this.ignoreCollision) {
      const resolved = this.collision.resolve(nx, nz, 0.3, this.character.container.position.y);
      nx = resolved.x;
      nz = resolved.z;
    }
    this.character.setPosition(
      nx,
      this.collision.groundAt(nx, nz, this.character.container.position.y),
      nz,
    );
    this.character.faceTowards(dx, dz, dt, 7);
    this.speed = 0.95;
  }

  private wander(dt: number): void {
    this.pauseTimer -= dt;
    this.walkTimer -= dt;

    if (this.moving) {
      const dx = this.targetX - this.x;
      const dz = this.targetZ - this.z;
      const distance = Math.hypot(dx, dz);
      if (distance < 0.35 || this.walkTimer <= 0) {
        this.moving = false;
        this.speed = 0;
        this.pauseTimer = 2 + this.random() * 5;
      } else {
        const step = 0.62 * dt;
        const nx = this.x + (dx / distance) * step;
        const nz = this.z + (dz / distance) * step;
        const resolved = this.collision.resolve(nx, nz, 0.3, this.character.container.position.y);
        this.character.setPosition(
          resolved.x,
          this.collision.groundAt(resolved.x, resolved.z, this.character.container.position.y),
          resolved.z,
        );
        this.character.faceTowards(dx, dz, dt, 4);
        this.speed = 0.62;
      }
      return;
    }

    if (this.pauseTimer <= 0) {
      const angle = this.random() * Math.PI * 2;
      const radius = 1.2 + this.random() * 2.4;
      this.targetX = this.homeX + Math.cos(angle) * radius;
      this.targetZ = this.homeZ + Math.sin(angle) * radius;
      this.walkTimer = 6 + this.random() * 6;
      this.moving = true;
    }
  }
}

export function createNpc(
  definition: LayoutNpc,
  character: Character,
  collision: CollisionWorld,
  index: number,
): Npc {
  return new Npc(definition, character, collision, index);
}

export function distanceToNpc(npc: Npc, x: number, z: number): number {
  return Math.hypot(npc.x - x, npc.z - z);
}
