import {
  colliderBlocks,
  groundHeightAt,
  resolveCircleCylinder,
  resolveCircleOBB,
  type CastleGround,
  type CylinderCollider,
  type OBB,
  type Walkable,
} from '../core/math';

export interface LayoutBuilding {
  name: string;
  x: number;
  z: number;
  rot: number;
  w: number;
  d: number;
  h: number;
  /** Some authored pieces, such as a balustrade, start above the ground. */
  bottom?: number;
}

export interface LayoutWall extends LayoutBuilding {}

export interface LayoutProp {
  type: 'box' | 'cylinder';
  x: number;
  z: number;
  rot?: number;
  w?: number;
  d?: number;
  r?: number;
  h: number;
  bottom?: number;
}

export interface LayoutInteractable {
  id: string;
  kind: 'sleep' | 'flavor' | 'activity' | 'cafe';
  x: number;
  z: number;
  radius: number;
  label: string;
  activity?: string;
  /** Height gate: the balcony viewpoint is not reachable from the courtyard. */
  minY?: number;
}

export interface LayoutNpc {
  id: string;
  x: number;
  z: number;
  yaw: number;
  character: string;
  idle: boolean;
  /** Baristas and cafe guests are driven by the cafe controller. */
  role?: string;
}

export interface LayoutZone {
  id: string;
  label: string;
  x: number;
  z: number;
  r: number;
}

export interface LayoutSeat {
  id: string;
  kind: 'chair' | 'bench' | 'lounger';
  x: number;
  z: number;
  yaw: number;
}

export interface LayoutWorld {
  /** Walkable radius of the map. Crossing it wraps to the opposite edge. */
  radius: number;
  /** North–south position of the waterline. Sea lies beyond it (more negative z). */
  waterlineZ?: number;
}

export interface TownLayout {
  spawn: { x: number; z: number; yaw: number };
  castle: CastleGround;
  buildings: LayoutBuilding[];
  walls: LayoutWall[];
  props: LayoutProp[];
  interactables: LayoutInteractable[];
  seats: LayoutSeat[];
  npcs: LayoutNpc[];
  zones: LayoutZone[];
  walkables?: Walkable[];
  world?: LayoutWorld;
}

export interface ResolvedPoint {
  x: number;
  z: number;
  blocked: boolean;
  /** True on the frame the player crossed the circular edge. */
  wrapped: boolean;
}

const DEFAULT_WORLD_RADIUS = 130;

export class CollisionWorld {
  readonly castle: CastleGround;
  readonly walkables: Walkable[];
  readonly world: LayoutWorld;
  private readonly boxes: OBB[] = [];
  private readonly cylinders: CylinderCollider[] = [];
  private readonly zones: LayoutZone[];

  constructor(layout: TownLayout) {
    this.castle = layout.castle;
    this.walkables = layout.walkables ?? [];
    this.world = layout.world ?? { radius: DEFAULT_WORLD_RADIUS };
    this.zones = [...layout.zones].sort((a, b) => a.r - b.r);

    for (const building of layout.buildings) {
      this.boxes.push({
        x: building.x,
        z: building.z,
        hw: building.w / 2 + 0.12,
        hd: building.d / 2 + 0.12,
        rot: building.rot,
        h: building.h,
        bottom: building.bottom ?? 0,
      });
    }

    for (const wall of layout.walls) {
      this.boxes.push({
        x: wall.x,
        z: wall.z,
        hw: wall.w / 2,
        hd: wall.d / 2,
        rot: wall.rot,
        h: wall.h,
        bottom: wall.bottom ?? 0,
      });
    }

    for (const prop of layout.props) {
      if (prop.type === 'box') {
        this.boxes.push({
          x: prop.x,
          z: prop.z,
          hw: (prop.w ?? 1) / 2,
          hd: (prop.d ?? 1) / 2,
          rot: prop.rot ?? 0,
          h: prop.h,
          bottom: prop.bottom ?? 0,
        });
      } else {
        this.cylinders.push({
          x: prop.x,
          z: prop.z,
          r: prop.r ?? 0.5,
          h: prop.h,
          bottom: prop.bottom ?? 0,
        });
      }
    }
  }

  /** Walkable height. `feetY` prevents snapping onto surfaces above the player. */
  groundAt(x: number, z: number, feetY = Number.POSITIVE_INFINITY): number {
    return groundHeightAt(x, z, this.castle, this.walkables, feetY);
  }

  /**
   * Resolve a circle against the town. Two passes handle corners where the
   * player is pressed between a building and a low wall. Colliders with a
   * bottom edge only block a player whose body actually reaches them.
   */
  resolve(x: number, z: number, radius: number, feetY: number): ResolvedPoint {
    let px = x;
    let pz = z;
    let blocked = false;

    const platformTop = this.castle.height + 0.12;
    const onPlatform = feetY > platformTop - 0.5;

    for (let pass = 0; pass < 2; pass += 1) {
      for (const box of this.boxes) {
        const bottom = box.bottom ?? 0;
        if (!colliderBlocks(feetY, bottom, box.h)) continue;
        const result = resolveCircleOBB(px, pz, radius, box);
        if (result.hit) {
          px = result.x;
          pz = result.z;
          blocked = true;
        }
      }
      for (const cylinder of this.cylinders) {
        const bottom = cylinder.bottom ?? 0;
        if (!colliderBlocks(feetY, bottom, cylinder.h)) continue;
        const result = resolveCircleCylinder(px, pz, radius, cylinder);
        if (result.hit) {
          px = result.x;
          pz = result.z;
          blocked = true;
        }
      }

      if (!onPlatform) {
        const dx = px - this.castle.x;
        const dz = pz - this.castle.z;
        const distance = Math.hypot(dx, dz);
        const stair = this.castle.stair;
        const north = this.castle.northStair;
        const pad = 0.6;
        const inSouthStair =
          Math.abs(px - stair.x) <= stair.halfWidth - 0.12 &&
          pz >= stair.zMin - pad &&
          pz <= stair.zMax + 0.2;
        const inNorthStair =
          !!north &&
          Math.abs(px - north.x) <= north.halfWidth - 0.12 &&
          pz >= north.zMin - 0.2 &&
          pz <= north.zMax + pad;
        const inStair = inSouthStair || inNorthStair;

        if (distance < this.castle.radius + radius && !inStair) {
          const limited = this.castle.radius + radius;
          const nx = distance > 1e-5 ? dx / distance : 0;
          const nz = distance > 1e-5 ? dz / distance : 1;
          px = this.castle.x + nx * limited;
          pz = this.castle.z + nz * limited;
          blocked = true;
        }
      }
    }

    const boundary = Math.hypot(px, pz);
    let wrapped = false;
    if (boundary > this.world.radius) {
      // Walk off one edge of the disc and appear at the antipodal point. A
      // straight line then crosses the whole map and returns to its start
      // instead of hitting an invisible wall. The tiny inset avoids wrapping
      // twice on the next frame while keeping the heading unchanged.
      const scale = (this.world.radius - 0.001) / boundary;
      px = -px * scale;
      pz = -pz * scale;
      wrapped = true;
    }

    return { x: px, z: pz, blocked, wrapped };
  }

  /**
   * Depth of the sea at a point. The water surface is a flat visual plane, so
   * lowering the character by this amount reads as wading without moving the
   * collision floor. It reaches chest depth before the wrap edge.
   */
  waterDepthAt(_x: number, z: number): number {
    const waterline = this.world.waterlineZ;
    if (waterline === undefined) return 0;
    const beyond = waterline - z;
    if (beyond <= 0) return 0;
    return Math.min(1.05, beyond * 0.032);
  }

  /** True when the player's feet are high enough for an elevated prompt. */
  canUse(item: LayoutInteractable, feetY: number): boolean {
    return item.minY === undefined || feetY + 0.4 >= item.minY;
  }

  /**
   * Fraction of the segment from the player's head to the wanted camera
   * position before it enters a solid. The rig uses this to pull the camera in
   * instead of letting it sit inside a wall, which matters most on the castle
   * balcony where the keep sits directly behind a south-facing player.
   */
  cameraClip(from: { x: number; y: number; z: number }, to: { x: number; y: number; z: number }, radius = 0.26): number {
    const dx = to.x - from.x;
    const dz = to.z - from.z;
    if (Math.abs(dx) + Math.abs(dz) < 1e-4) return 1;

    const minY = Math.min(from.y, to.y);
    const maxY = Math.max(from.y, to.y);
    let best = 1;

    const slab = (f: number, d: number, half: number): [number, number] | null => {
      if (Math.abs(d) < 1e-6) return Math.abs(f) <= half ? [0, 1] : null;
      let t1 = (-half - f) / d;
      let t2 = (half - f) / d;
      if (t1 > t2) [t1, t2] = [t2, t1];
      return [t1, t2];
    };

    for (const box of this.boxes) {
      const bottom = box.bottom ?? 0;
      if (maxY < bottom || minY > bottom + box.h) continue;
      const cos = Math.cos(box.rot);
      const sin = Math.sin(box.rot);
      const fx = from.x - box.x;
      const fz = from.z - box.z;
      const lx = fx * cos - fz * sin;
      const lz = fx * sin + fz * cos;
      const ldx = dx * cos - dz * sin;
      const ldz = dx * sin + dz * cos;
      const xSlab = slab(lx, ldx, box.hw + radius);
      const zSlab = slab(lz, ldz, box.hd + radius);
      if (!xSlab || !zSlab) continue;
      const tMin = Math.max(xSlab[0], zSlab[0]);
      const tMax = Math.min(xSlab[1], zSlab[1]);
      if (tMin <= tMax && tMin > 0.001 && tMin < best) best = tMin;
    }

    for (const cylinder of this.cylinders) {
      const bottom = cylinder.bottom ?? 0;
      if (maxY < bottom || minY > bottom + cylinder.h) continue;
      const r = cylinder.r + radius;
      const fx = from.x - cylinder.x;
      const fz = from.z - cylinder.z;
      const a = dx * dx + dz * dz;
      if (a < 1e-6) continue;
      const b = 2 * (fx * dx + fz * dz);
      const c = fx * fx + fz * fz - r * r;
      const discriminant = b * b - 4 * a * c;
      if (discriminant < 0) continue;
      const t = (-b - Math.sqrt(discriminant)) / (2 * a);
      if (t > 0.001 && t < best) best = t;
    }

    return best;
  }

  zoneAt(x: number, z: number): LayoutZone | null {
    let best: LayoutZone | null = null;
    for (const zone of this.zones) {
      const distance = Math.hypot(x - zone.x, z - zone.z);
      if (distance <= zone.r) {
        best = zone;
        break;
      }
    }
    return best;
  }
}
