/** One full day, in game minutes. */
export const DAY_MINUTES = 24 * 60;
/** The hour a new day starts after sleeping. */
export const WAKE_MINUTES = 6 * 60;
/** Fallback when "start from real time" is disabled or the device clock is invalid. */
export const DEFAULT_START_MINUTES = WAKE_MINUTES;
/** The whole day lasts twelve real minutes. */
export const DAY_DURATION_SECONDS = 12 * 60;
export const MINUTES_PER_SECOND = DAY_MINUTES / DAY_DURATION_SECONDS;

export type DayPhase = 'morning' | 'day' | 'evening' | 'night';

const formatters = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string): Intl.DateTimeFormat {
  let value = formatters.get(locale);
  if (!value) {
    value = new Intl.DateTimeFormat(locale === 'id' ? 'id-ID' : 'en-GB', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    formatters.set(locale, value);
  }
  return value;
}

/** Fold any minute value into [0, 1440). */
export function wrapMinutes(minutes: number): number {
  if (!Number.isFinite(minutes)) return DEFAULT_START_MINUTES;
  return ((minutes % DAY_MINUTES) + DAY_MINUTES) % DAY_MINUTES;
}

/** Minutes since local midnight, including the seconds fraction for a round hour. */
export function minutesFromDate(date: Date): number {
  return wrapMinutes(date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60);
}

/** A quiet greeting phase that matches the clock and the sky. */
export function phaseForMinutes(minutes: number): DayPhase {
  const time = wrapMinutes(minutes);
  if (time >= 5 * 60 && time < 9 * 60) return 'morning';
  if (time >= 9 * 60 && time < 17 * 60) return 'day';
  if (time >= 17 * 60 && time < 20 * 60) return 'evening';
  return 'night';
}

export function formatMinutes(minutes: number, locale: string): string {
  const time = wrapMinutes(minutes);
  const hours = Math.floor(time / 60);
  const rest = Math.floor(time % 60);
  const date = new Date(2026, 0, 1, hours, rest, 0, 0);
  return formatter(locale).format(date);
}

export class GameClock {
  minutes = DEFAULT_START_MINUTES;
  day = 1;

  constructor(minutes = DEFAULT_START_MINUTES, day = 1) {
    this.minutes = wrapMinutes(minutes);
    this.day = Math.max(1, Math.floor(day));
  }

  /** Advance time. Returns true when the day rolled over. */
  update(dt: number): boolean {
    this.minutes += dt * MINUTES_PER_SECOND;
    if (this.minutes >= DAY_MINUTES) {
      this.minutes = wrapMinutes(this.minutes);
      this.day += 1;
      return true;
    }
    return false;
  }

  /** Sleep until the next morning. */
  nextDay(): void {
    this.minutes = WAKE_MINUTES;
    this.day += 1;
  }

  setTime(minutes: number): void {
    this.minutes = wrapMinutes(minutes);
  }

  /** 0 at midnight, 0.5 at noon, approaching 1 just before midnight. */
  get dayProgress(): number {
    return this.minutes / DAY_MINUTES;
  }

  get phase(): DayPhase {
    return phaseForMinutes(this.minutes);
  }

  /** Late enough that the lamps are on, including the hours before sunrise. */
  get isLate(): boolean {
    return this.minutes >= 20 * 60 + 30 || this.minutes < 5 * 60;
  }

  format(locale: string): string {
    return formatMinutes(this.minutes, locale);
  }

  isoDay(): string {
    return `day-${this.day}`;
  }
}
