import './style.css';
import { Game } from './app/Game';
import { detectLocale } from './core/locale';
import { loadSave } from './core/save';
import { hasStoredSettings, loadSettings } from './core/settings';
import { initI18n } from './i18n';

async function main(): Promise<void> {
  const settings = loadSettings();

  // A previously chosen language always wins. On the first visit, ask the
  // network where the player is; the lookup has its own short timeout.
  if (!hasStoredSettings()) {
    settings.language = await detectLocale();
  }

  await initI18n(settings.language);

  const canvas = document.getElementById('scene');
  const previewCanvas = document.getElementById('preview-canvas');
  if (!(canvas instanceof HTMLCanvasElement) || !(previewCanvas instanceof HTMLCanvasElement)) {
    throw new Error('Canvas elements are missing');
  }

  const game = new Game(canvas, previewCanvas, settings, loadSave());
  await game.boot();

  if (import.meta.env.DEV) {
    (window as unknown as { __dailyLife?: Game }).__dailyLife = game;
  }
}

void main().catch((error: unknown) => {
  console.error(error);
  const label = document.getElementById('loading-label');
  if (label) label.textContent = 'Daily Life could not start. Reload the page to try again.';
});
