import * as THREE from 'three';
import { Character, type CharacterLibrary } from './character';
import type { CharacterId } from './catalog';
import { createCurveUniforms } from '../render/curved';

/** Small independent renderer for the character select screen. */
export class CharacterPreview {
  private renderer: THREE.WebGLRenderer | null = null;
  private scene: THREE.Scene | null = null;
  private camera: THREE.PerspectiveCamera | null = null;
  private character: Character | null = null;
  private active = false;
  private dragging = false;
  private yawOffset = 0;
  private lastX = 0;
  private elapsed = 0;
  private resizeObserver: ResizeObserver | null = null;

  constructor(
    private readonly canvas: HTMLCanvasElement,
    private readonly library: CharacterLibrary,
  ) {}

  private ensure(): void {
    if (this.renderer) return;
    const renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.shadowMap.enabled = false;
    this.renderer = renderer;

    const scene = new THREE.Scene();
    this.scene = scene;

    const camera = new THREE.PerspectiveCamera(32, 1, 0.1, 20);
    camera.position.set(0, 1.16, 3.55);
    camera.lookAt(0, 0.9, 0);
    this.camera = camera;

    const key = new THREE.DirectionalLight(0xfff1dc, 2.6);
    key.position.set(2.4, 4.2, 3.4);
    scene.add(key);
    const fill = new THREE.DirectionalLight(0xbfd3dc, 1.1);
    fill.position.set(-3, 2, 1.4);
    scene.add(fill);
    const rim = new THREE.DirectionalLight(0xe8c39a, 1.4);
    rim.position.set(-1.5, 3, -3.5);
    scene.add(rim);
    scene.add(new THREE.HemisphereLight(0xf0e6d6, 0x4b4a44, 0.9));

    const shadowCanvas = document.createElement('canvas');
    shadowCanvas.width = 128;
    shadowCanvas.height = 128;
    const ctx = shadowCanvas.getContext('2d');
    if (ctx) {
      const gradient = ctx.createRadialGradient(64, 64, 4, 64, 64, 62);
      gradient.addColorStop(0, 'rgba(30, 32, 28, 0.36)');
      gradient.addColorStop(0.6, 'rgba(30, 32, 28, 0.14)');
      gradient.addColorStop(1, 'rgba(30, 32, 28, 0)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, 128, 128);
    }
    const shadowTexture = new THREE.CanvasTexture(shadowCanvas);
    const shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(1.9, 1.9),
      new THREE.MeshBasicMaterial({ map: shadowTexture, transparent: true, depthWrite: false }),
    );
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = 0.002;
    scene.add(shadow);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(this.canvas);
    this.resize();

    this.canvas.addEventListener('pointerdown', this.onPointerDown);
    window.addEventListener('pointermove', this.onPointerMove);
    window.addEventListener('pointerup', this.onPointerUp);
  }

  private onPointerDown = (event: PointerEvent): void => {
    this.dragging = true;
    this.lastX = event.clientX;
  };

  private onPointerMove = (event: PointerEvent): void => {
    if (!this.dragging) return;
    this.yawOffset += (event.clientX - this.lastX) * 0.01;
    this.yawOffset = THREE.MathUtils.clamp(this.yawOffset, -1.1, 1.1);
    this.lastX = event.clientX;
  };

  private onPointerUp = (): void => {
    this.dragging = false;
  };

  private resize(): void {
    if (!this.renderer || !this.camera) return;
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;
    if (width < 2 || height < 2) return;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  show(id: CharacterId): void {
    this.ensure();
    if (!this.scene) return;
    if (this.character) {
      this.character.dispose();
      this.character = null;
    }
    const character = this.library.create(id, createCurveUniforms(0));
    character.setPosition(0, 0, 0);
    character.setYaw(Math.PI);
    character.greet('hello');
    this.scene.add(character.container);
    this.character = character;
    this.yawOffset = 0;
    this.elapsed = 0;
    this.resize();
  }

  setActive(active: boolean): void {
    this.active = active;
    if (active) {
      this.resize();
      this.canvas.style.visibility = 'visible';
    }
  }

  update(dt: number): void {
    if (!this.active || !this.renderer || !this.scene || !this.camera || !this.character) return;
    this.elapsed += dt;
    this.character.container.rotation.y =
      Math.PI + Math.sin(this.elapsed * 0.55) * 0.16 + this.yawOffset;
    this.character.updatePreview(dt);
    this.renderer.render(this.scene, this.camera);
  }

  dispose(): void {
    this.resizeObserver?.disconnect();
    this.canvas.removeEventListener('pointerdown', this.onPointerDown);
    window.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
    this.character?.dispose();
    this.renderer?.dispose();
    this.renderer = null;
  }
}
