import * as THREE from 'three';
import { CharacterLibrary } from '../characters/character';
import { CharacterPreview } from '../characters/preview';
import { isCharacterId, OUTFITS, type CharacterId, type Gender } from '../characters/catalog';
import { Input } from '../core/input';
import { createSave, loadSave, writeSave, clearSave, type SaveData } from '../core/save';
import { saveSettings, type Locale, type Quality, type Settings } from '../core/settings';
import { Ambience } from '../gameplay/audio';
import { Cafe } from '../gameplay/cafe';
import { BARISTA_STAND } from '../gameplay/cafeData';
import { GameClock, minutesFromDate } from '../gameplay/clock';
import { greetingKeyForPhase } from '../gameplay/greeting';
import { Npc } from '../gameplay/npc';
import { Player } from '../gameplay/player';
import { t, tList, setLocale } from '../i18n';
import { CameraRig } from '../render/camera';
import { createCurveUniforms, setCurveStrength } from '../render/curved';
import { advanceWind } from '../render/wind';
import {
  applyQuality,
  createSceneContext,
  resize,
  updateEnvironment,
  type SceneContext,
} from '../render/renderer';
import { Ui, type JournalEntryView } from '../ui/ui';
import type { BubbleView } from '../ui/bubbles';
import type { LayoutInteractable, LayoutSeat } from '../world/collision';
import { loadTown, type Town } from '../world/town';

type State = 'boot' | 'title' | 'select' | 'playing' | 'paused';

type ActivityId = 'coffee' | 'greet' | 'sunset';
const ACTIVITY_IDS: ActivityId[] = ['coffee', 'greet', 'sunset'];

const FLAVOR_BY_ID: Record<string, string> = {
  home_door: 'sleep',
  fountain: 'fountain',
  cafe: 'cafe',
  bakery: 'bakery',
  florist: 'florist',
  viewpoint: 'viewpoint',
  castle_gate: 'castle',
  beach: 'beach',
  palm_grove: 'palm',
};

type Nearby =
  | { kind: 'npc'; npc: Npc; distance: number }
  | { kind: 'seat'; seat: LayoutSeat; distance: number }
  | { kind: 'object'; item: LayoutInteractable; distance: number };

const TITLE_MINUTES = 9 * 60 + 30;

/**
 * Camera angles used when the player settles on a sun lounger. Viewed from
 * straight behind, the raised backrest covers the body. Sitting uses a
 * three-quarter view that keeps the sea in frame; lying swings a little
 * further to the side so the whole body and face stay readable against the
 * pillow.
 */
const LOUNGER_SIT_VIEW = 1.25;
const LOUNGER_LIE_VIEW = 1.8;

/** New games begin on the player's own clock, matching the title screen. */
function localStartMinutes(realTime: boolean): number {
  return realTime ? minutesFromDate(new Date()) : TITLE_MINUTES;
}

export class Game {
  private readonly ui: Ui;
  private readonly context: SceneContext;
  private readonly curve = createCurveUniforms();
  private readonly library = new CharacterLibrary();
  private readonly preview: CharacterPreview;
  private readonly input: Input;
  private readonly rig: CameraRig;
  private readonly audio = new Ambience();
  private readonly focus = new THREE.Vector3(0, 3.2, 0);

  private settings: Settings;
  private save: SaveData | null;
  private town: Town | null = null;
  private player: Player | null = null;
  private npcs: Npc[] = [];
  private cafe: Cafe | null = null;
  private clock = new GameClock();
  private titleMinutes = TITLE_MINUTES;

  private state: State = 'boot';
  private selectedGender: Gender = 'male';
  private selectedOutfit: CharacterId = 'male_1';
  private activities: Record<string, boolean> = {};
  private nearby: Nearby | null = null;
  private promptKey: string | null = null;
  private talkingNpc: Npc | null = null;
  private pendingSleep = false;
  private lateNotified = false;
  private resetting = false;
  private lastFrame = 0;
  private hudAccumulator = 0;
  private toastCooldown = 0;
  private bubbleAnchor = new THREE.Vector3();

  constructor(
    canvas: HTMLCanvasElement,
    previewCanvas: HTMLCanvasElement,
    settings: Settings,
    save: SaveData | null,
  ) {
    this.settings = { ...settings };
    this.save = save;
    this.context = createSceneContext(canvas, this.settings.quality, this.curve);
    setCurveStrength(this.curve, this.settings.curve);
    this.rig = new CameraRig(this.context.camera);
    this.rig.sensitivity = this.settings.sensitivity;
    this.rig.setObstructionResolver((from, to) =>
      this.town ? this.town.collision.cameraClip(from, to) : 1,
    );
    this.preview = new CharacterPreview(previewCanvas, this.library);
    this.input = new Input(canvas);

    this.ui = new Ui({
      onStart: () => this.handleStart(),
      onContinue: () => this.handleContinue(),
      onSelectBack: () => this.handleSelectBack(),
      onConfirm: () => this.handleConfirm(),
      onGender: (gender) => this.handleGender(gender),
      onOutfit: (id) => this.handleOutfit(id),
      onLanguage: (locale) => void this.handleLanguage(locale),
      onOpenSettings: (fromGame) => this.handleOpenSettings(fromGame),
      onCloseSettings: () => this.handleCloseSettings(),
      onOpenCredits: () => this.ui.openCredits(),
      onCloseCredits: () => this.ui.closeCredits(),
      onPause: () => this.openPause(),
      onResume: () => this.handleCloseSettings(),
      onReset: () => this.handleReset(),
      onJournalOpen: () => this.setJournal(true),
      onJournalClose: () => this.setJournal(false),
      onDialogNext: () => this.ui.advanceDialog(),
      onDialogClosed: () => this.handleDialogClosed(),
      onInteract: () => this.triggerInteract(),
      onQuality: (quality) => this.handleQuality(quality),
      onCurve: (value) => this.handleCurve(value),
      onRealTimeStart: (enabled) => this.handleRealTimeStart(enabled),
      onSensitivity: (value) => this.handleSensitivity(value),
      onVolume: (value) => this.handleVolume(value),
      onCafeHover: (id) => this.cafe?.describe(id),
      onCafeSelect: (id) => this.cafe?.orderItem(id),
      onCafeClose: () => this.cafe?.closeMenu(),
    });
    this.ui.syncSettings(this.settings);

    window.addEventListener('resize', this.handleResize);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.persist();
    });
    window.addEventListener('beforeunload', () => this.persist());
    this.audio.setVolume(this.settings.volume);
  }

  private handleResize = (): void => {
    resize(this.context.renderer, this.context.camera);
  };

  async boot(): Promise<void> {
    // The loading screen and title share the hour the device reported when the
    // page opened. The new game refreshes it again when the player confirms.
    this.titleMinutes = localStartMinutes(this.settings.realTimeStart);
    this.ui.showLocalTime(this.titleMinutes);
    this.ui.showLoading();
    this.ui.setLoading(0.04, 'loading.preparing');

    try {
      this.town = await loadTown(this.curve, (fraction) => {
        this.ui.setLoading(0.04 + fraction * 0.36, fraction >= 1 ? 'loading.characters' : 'loading.world');
      });
      this.context.scene.add(this.town.root);
      this.ui.setLoading(0.42, 'loading.characters');

      await this.library.loadAll((fraction) => {
        this.ui.setLoading(0.42 + fraction * 0.48, 'loading.characters');
      });

      for (const [index, definition] of this.town.layout.npcs.entries()) {
        if (!isCharacterId(definition.character)) continue;
        const character = this.library.create(definition.character, this.curve);
        this.context.scene.add(character.container);
        this.npcs.push(new Npc(definition, character, this.town.collision, index + 1));
      }

      this.cafe = new Cafe(this.context.scene, this.town.layout, this.npcs, {
        onOpenMenu: (name, shift) => this.ui.openCafeMenu(name, shift),
        onCloseMenu: () => this.ui.closeCafeMenu(),
        onToast: (message) => this.ui.toast(message),
        onServed: () => this.markActivity('coffee'),
        onPlayerSay: (message) => this.player?.character.say(message),
        playerSeatId: () => this.player?.seatId ?? null,
      });
      this.cafe.reset(1, this.titleMinutes);

      this.ui.setLoading(0.96, 'loading.almost');
      this.ui.showTitle(Boolean(this.save));
      this.state = 'title';
      this.rig.updateCinematic(0.016);
      this.lastFrame = performance.now();
      requestAnimationFrame(this.tick);
    } catch (error) {
      console.error(error);
      this.ui.setLoading(1, 'loading.error');
    }
  }

  private tick = (now: number): void => {
    const dt = Math.min(0.05, Math.max(0, (now - this.lastFrame) / 1000));
    this.lastFrame = now;
    this.toastCooldown = Math.max(0, this.toastCooldown - dt);

    this.handleKeys(dt);
    this.update(dt);
    this.render();
    this.updateBubbles();

    this.input.endFrame();
    requestAnimationFrame(this.tick);
  };

  private update(dt: number): void {
    if (!this.town) return;
    advanceWind(dt);

    if (this.state === 'playing') {
      const canPlay =
        !this.ui.isDialogOpen &&
        !this.ui.isJournalOpen &&
        !this.ui.isPauseOpen &&
        !this.ui.isCreditsOpen &&
        !this.ui.isCafeMenuOpen;

      if (this.player) {
        // A lying character has a much lower silhouette; lower the orbit target
        // so the camera looks at the body instead of the empty air above it.
        this.rig.setTargetHeight(this.player.isLying ? 0.85 : 1.42);
        // Leaving a seat (walking or teleporting away) drops any pose framing.
        if (!this.player.seated) this.rig.releaseOrbit();
        if (canPlay) {
          const look = this.input.consumeLook();
          this.rig.update(dt, this.player.position, look);
          const axis = this.input.moveAxis();
          // Walking away from a seat stands the character up first, which
          // keeps the interaction out of the way of normal movement.
          if (
            this.player.seated &&
            (Math.abs(axis.x) > 0.01 || Math.abs(axis.y) > 0.01 || this.input.wasPressed('jump'))
          ) {
            this.player.stand();
          }
          const forward = this.rig.forward(new THREE.Vector3());
          const right = this.rig.right(new THREE.Vector3());
          const moveX = forward.x * axis.y + right.x * axis.x;
          const moveZ = forward.z * axis.y + right.z * axis.x;
          this.player.update(dt, moveX, moveZ, this.input.isDown('run'), this.input.wasPressed('jump'), {
            onFootstep: (running) => this.audio.footstep(running),
          });
          // A wrap moves the player to the far edge of the disc. Pull the
          // camera with them on the same frame to avoid a long interpolation
          // across the whole map.
          if (this.player.consumeWrapped()) this.rig.snap(this.player.position);
          this.clock.update(dt) && this.handleDayRollover();
          this.detectNearby();
          this.updateHudProgress(dt);
        } else {
          this.input.consumeLook();
          this.rig.update(dt, this.player.position, { x: 0, y: 0 });
          this.player.character.update(dt, { speed: 0, airborne: !this.player.grounded });
          this.ui.hidePrompt();
          this.nearby = null;
          this.promptKey = null;
        }
      }

      this.audio.update(dt, this.clock.phase);
      if (!this.lateNotified && this.clock.isLate) {
        this.lateNotified = true;
        this.ui.toast(t('toast.timeToGoHome'), 4200);
      }
      // On the castle balcony the keep sits right behind the player, so the
      // camera has to hug the head. Hide the model instead of filling the
      // screen with the back of it. 1.8 m is roughly the point where the
      // character covers a third of the view.
      if (this.player) {
        this.player.character.container.visible = this.rig.clearance > 1.8;
      }
    } else if (this.state === 'title' || this.state === 'select') {
      this.rig.updateCinematic(dt);
      this.input.consumeLook();
      this.audio.update(dt, 'evening');
    } else {
      this.input.consumeLook();
    }

    // Café scripts (shift swaps, brewing, serving, ambient guests) advance
    // before the NPCs render their new pose for this frame.
    const cafeMinutes =
      this.state === 'playing' || this.state === 'paused' ? this.clock.minutes : this.titleMinutes;
    this.cafe?.update(this.state === 'playing' ? dt : 0, this.clock.day, cafeMinutes);

    for (const npc of this.npcs) {
      const playerPosition = this.player?.position;
      npc.update(
        this.state === 'paused' ? 0 : dt,
        playerPosition?.x ?? this.context.camera.position.x,
        playerPosition?.z ?? this.context.camera.position.z,
        this.state === 'playing' ? this.greetingText() : '',
      );
    }

    if (this.state === 'select') {
      this.preview.update(dt);
    }

    if (this.player) this.focus.set(this.player.position.x, this.player.position.y + 1.4, this.player.position.z);
    else this.focus.set(0, 3.2, 0);

    updateEnvironment(this.context, this.town.materials, {
      minutes: this.state === 'playing' || this.state === 'paused' ? this.clock.minutes : this.titleMinutes,
      playerPosition: this.focus,
    });
    this.ui.updateCafePreview(dt);
  }

  private render(): void {
    this.context.renderer.render(this.context.scene, this.context.camera);
  }

  /** Project each active speech bubble to screen space above its speaker. */
  private updateBubbles(): void {
    if (
      this.state !== 'playing' ||
      this.ui.isPauseOpen ||
      this.ui.isCreditsOpen ||
      this.ui.isJournalOpen
    ) {
      this.ui.updateBubbles([]);
      return;
    }

    const camera = this.context.camera;
    const views: BubbleView[] = [];
    const collect = (id: string, character: { bubbleText: string | null; bubbleAnchor: (out: THREE.Vector3) => THREE.Vector3 }): void => {
      const text = character.bubbleText;
      if (!text) return;
      const anchor = character.bubbleAnchor(this.bubbleAnchor).project(camera);
      const x = (anchor.x * 0.5 + 0.5) * window.innerWidth;
      const y = (-anchor.y * 0.5 + 0.5) * window.innerHeight;
      const visible =
        anchor.z > -1 &&
        anchor.z < 1 &&
        x > -260 &&
        x < window.innerWidth + 260 &&
        y > -80 &&
        y < window.innerHeight + 140;
      views.push({ id, text, x, y, visible });
    };

    if (this.player) collect('player', this.player.character);
    for (const npc of this.npcs) collect(`npc:${npc.definition.id}`, npc.character);
    this.ui.updateBubbles(views);
  }

  private handleKeys(dt: number): void {
    void dt;
    const pause = this.input.wasPressed('pause');

    if (this.state === 'paused') {
      if (pause) this.handleCloseSettings();
      return;
    }

    if (this.state !== 'playing') {
      if (pause) {
        if (this.ui.isCreditsOpen) this.ui.closeCredits();
        else if (this.ui.isPauseOpen) this.ui.closeSettings();
      }
      return;
    }

    // Escape closes the menu before it becomes a pause request.
    if (this.ui.isCafeMenuOpen) {
      if (pause) this.cafe?.closeMenu();
      return;
    }

    if (pause) {
      this.openPause();
      return;
    }

    if (this.input.wasPressed('journal') && !this.ui.isDialogOpen) {
      this.setJournal(!this.ui.isJournalOpen);
      return;
    }

    if (this.ui.isJournalOpen) return;

    if (this.ui.isDialogOpen) {
      if (this.input.wasPressed('interact') || this.input.wasPressed('jump')) this.ui.advanceDialog();
      return;
    }

    if (this.input.wasPressed('greet')) this.triggerGreeting();
    if (this.input.wasPressed('interact')) this.triggerInteract();
  }

  /** Raise a hand and, if a neighbour is within earshot, wave back. */
  private triggerGreeting(): void {
    if (!this.player) return;
    const greeting = this.greetingText();
    if (this.player.seated) {
      // A small nod still reads while sitting; do not force the player up.
      this.player.character.greet('hello');
      this.player.character.say(greeting);
      return;
    }
    this.player.character.greet('hello');
    this.player.character.say(greeting);
    const { x, z } = this.player.position;
    let greeted = false;
    for (const npc of this.npcs) {
      if (Math.hypot(npc.x - x, npc.z - z) <= 4.2) {
        npc.greet('wave', greeting);
        greeted = true;
      }
    }
    if (greeted) this.markActivity('greet');
  }

  /** The bubble line that matches the current hour. */
  private greetingText(): string {
    return t(greetingKeyForPhase(this.clock.phase));
  }

  private detectNearby(): void {
    if (!this.player || !this.town) return;
    const { x, z } = this.player.position;

    // While seated the only actions are standing up or, on a lounger,
    // shifting between sitting and lying down.
    if (this.player.seated) {
      const seat = this.town.layout.seats.find((entry) => entry.id === this.player?.seatId);
      this.nearby = seat ? { kind: 'seat', seat, distance: 0 } : null;
      let key = 'seat:stand';
      let label = t('interact.stand');
      if (seat?.kind === 'lounger') {
        key = this.player.isLying ? `seat:sitUp:${seat.id}` : `seat:lie:${seat.id}`;
        label = t(this.player.isLying ? 'interact.sitUp' : 'interact.lie');
      }
      if (this.promptKey !== key) {
        this.promptKey = key;
        this.ui.showPrompt(label);
      }
      return;
    }

    let best: Nearby | null = null;
    let bestDistance = Infinity;

    for (const npc of this.npcs) {
      // Baristas are ordered from the counter, not chatted to mid-shift.
      if (npc.definition.role === 'barista') continue;
      const distance = Math.hypot(npc.x - x, npc.z - z);
      if (distance <= 2.35 && distance < bestDistance) {
        bestDistance = distance;
        best = { kind: 'npc', npc, distance };
      }
    }

    // Seats win over broad zone interactions such as the cafe table, so a
    // chair right behind you is not shadowed by the whole-terrace prompt.
    if (!best) {
      for (const seat of this.town.layout.seats) {
        const radius = seat.kind === 'chair' ? 1.35 : seat.kind === 'lounger' ? 1.55 : 1.25;
        const distance = Math.hypot(seat.x - x, seat.z - z);
        if (distance <= radius && distance < bestDistance) {
          bestDistance = distance;
          best = { kind: 'seat', seat, distance };
        }
      }
    }

    if (!best) {
      for (const item of this.town.layout.interactables) {
        if (!this.town.collision.canUse(item, this.player.position.y)) continue;
        const distance = Math.hypot(item.x - x, item.z - z);
        if (distance <= item.radius && distance < bestDistance) {
          bestDistance = distance;
          best = { kind: 'object', item, distance };
        }
      }
    }

    this.nearby = best;

    let label: string | null = null;
    let key: string | null = null;
    if (best?.kind === 'npc') {
      key = `npc:${best.npc.definition.id}`;
      label = `${t('interact.talk')} · ${t(`npc.${best.npc.definition.id}.name`)}`;
    } else if (best?.kind === 'seat') {
      key = `seat:${best.seat.id}`;
      label = t(
        best.seat.kind === 'bench'
          ? 'interact.sitBench'
          : best.seat.kind === 'lounger'
            ? 'interact.sunbathe'
            : 'interact.sitChair',
      );
    } else if (best?.kind === 'object') {
      key = `item:${best.item.id}`;
      label = t(best.item.label);
    }

    if (key === this.promptKey) return;
    this.promptKey = key;
    if (label) this.ui.showPrompt(label);
    else this.ui.hidePrompt();
  }

  private triggerInteract(): void {
    if (!this.player || !this.nearby) return;
    const target = this.nearby;

    if (target.kind === 'seat') {
      if (this.player.seated) {
        if (target.seat.kind === 'lounger') {
          if (this.player.isLying) {
            this.player.sitUp();
            this.rig.orbitTo(target.seat.yaw + LOUNGER_SIT_VIEW);
          } else {
            this.player.lieDown();
            this.rig.orbitTo(target.seat.yaw + LOUNGER_LIE_VIEW);
          }
        } else {
          this.player.stand();
        }
      } else {
        this.player.sit(target.seat);
        if (target.seat.kind === 'lounger') {
          // Directly behind a lounger the raised backrest hides the body, so
          // frame the seat from the side. The player can still orbit freely.
          this.rig.orbitTo(target.seat.yaw + LOUNGER_SIT_VIEW);
        }
        this.cafe?.onPlayerSeated(target.seat);
      }
      this.nearby = null;
      this.promptKey = null;
      this.ui.hidePrompt();
      return;
    }

    if (target.kind === 'npc') {
      const npc = target.npc;
      const id = npc.definition.id;
      const name = t(`npc.${id}.name`);
      const lines = tList(`npc.${id}.lines`);
      const greeting = this.greetingText();
      npc.talking = true;
      npc.greet('wave', greeting);
      this.player.character.greet('hello');
      this.player.character.say(greeting);
      this.talkingNpc = npc;
      this.markActivity('greet');
      this.openDialog(name, lines, OUTFITS[npc.definition.character as CharacterId]?.swatch ?? '#31453b', {
        kind: 'character',
        id: npc.definition.character as CharacterId,
      });
      return;
    }

    const item = target.item;
    if (item.kind === 'cafe') {
      // Turn to the barista before the menu opens, so the conversation reads
      // as a face-to-face order rather than a remote popup.
      const yaw = Math.atan2(
        -(BARISTA_STAND.x - this.player.position.x),
        -(BARISTA_STAND.z - this.player.position.z),
      );
      this.player.yaw = yaw;
      this.player.character.setYaw(yaw);
      this.player.velocity.set(0, 0, 0);
      this.cafe?.openMenu();
      this.nearby = null;
      this.promptKey = null;
      this.ui.hidePrompt();
      return;
    }

    if (item.kind === 'sleep') {
      this.pendingSleep = true;
    }

    if (item.kind === 'activity' && item.activity) {
      this.markActivity(item.activity as ActivityId);
    }

    const flavor = FLAVOR_BY_ID[item.id];
    if (flavor) {
      const title = t(`flavor.${flavor}.title`);
      const lines = tList(`flavor.${flavor}.lines`);
      this.openDialog(title, lines, '#31453b', { kind: 'flavor', id: flavor });
    }
  }

  private openDialog(
    speaker: string,
    lines: string[],
    swatch: string,
    portrait?: { kind: 'character'; id: CharacterId } | { kind: 'flavor'; id: string },
  ): void {
    this.player?.velocity.set(0, 0, 0);
    const accent = new THREE.Color(swatch).multiplyScalar(0.55).getStyle();
    this.ui.openDialog(speaker, lines.length ? lines : [''], accent, portrait);
    this.ui.hidePrompt();
    this.nearby = null;
    this.promptKey = null;
  }

  private handleDialogClosed(): void {
    if (this.talkingNpc) {
      this.talkingNpc.talking = false;
      this.talkingNpc = null;
    }
    if (this.pendingSleep) {
      this.pendingSleep = false;
      this.nextDay(true);
    }
  }

  private markActivity(id: ActivityId): boolean {
    if (this.activities[id]) return false;
    this.activities[id] = true;
    this.ui.toast(t('toast.activityDone'));
    this.audio.bell();
    this.updateHud(true);
    this.persist();
    return true;
  }

  private setJournal(open: boolean): void {
    if (open) {
      this.updateHud(true);
      this.player?.velocity.set(0, 0, 0);
    }
    this.ui.setJournalOpen(open);
    if (open) this.ui.hidePrompt();
  }

  private updateHudProgress(dt: number): void {
    this.hudAccumulator += dt;
    if (this.hudAccumulator >= 0.2) {
      this.hudAccumulator = 0;
      this.updateHud();
    }
  }

  private updateHud(_forceJournal = false): void {
    if (!this.player || !this.town) return;
    const zone = this.town.collision.zoneAt(this.player.position.x, this.player.position.z);
    const place = zone ? t(zone.label) : t('zone.plaza');
    const activities = ACTIVITY_IDS.map((id) => ({
      id,
      name: t(`activities.${id}.name`),
      done: Boolean(this.activities[id]),
    }));
    this.ui.updateHud({
      day: this.clock.day,
      time: this.clock.format(this.settings.language),
      place,
      activities,
    });
    const entries: JournalEntryView[] = ACTIVITY_IDS.map((id) => ({
      id,
      name: t(`activities.${id}.name`),
      desc: t(`activities.${id}.desc`),
      done: Boolean(this.activities[id]),
    }));
    this.ui.updateJournal(entries);
  }

  private handleDayRollover(): void {
    // Midnight starts a new calendar day without moving the player. Only
    // sleeping returns them to the house.
    this.resetDayState(false, false);
  }

  /** Called after sleep: advance the calendar, fade, and wake at home. */
  private nextDay(fade: boolean): void {
    this.clock.nextDay();
    this.resetDayState(fade, true);
  }

  private resetDayState(fade: boolean, teleport: boolean): void {
    const finish = (): void => {
      this.activities = {};
      this.lateNotified = false;
      if (teleport && this.player && this.town) {
        this.player.teleport(this.town.layout.spawn.x, this.town.layout.spawn.z, 0);
        this.rig.reset(0);
        this.rig.update(0.016, this.player.position, { x: 0, y: 0 }, true);
      }
      this.cafe?.reset(this.clock.day, this.clock.minutes);
      this.audio.bell();
      this.ui.toast(t('toast.newDay'), 3400);
      this.updateHud(true);
      this.persist();
      if (fade) this.ui.fadeFromBlack();
    };

    if (fade) this.ui.fadeToBlack(finish);
    else finish();
  }

  private handleStart(): void {
    void this.audio.start();
    this.ui.fadeToBlack(() => {
      this.ui.showSelect();
      this.preview.show(this.selectedOutfit);
      this.preview.setActive(true);
      this.ui.selectGender(this.selectedGender, this.selectedOutfit);
      this.state = 'select';
      this.ui.fadeFromBlack();
    });
  }

  private handleSelectBack(): void {
    this.preview.setActive(false);
    this.ui.showTitle(Boolean(this.save));
    this.state = 'title';
  }

  private handleGender(gender: Gender): void {
    const first = gender === 'male' ? 'male_1' : 'female_1';
    this.selectedGender = gender;
    this.selectedOutfit = first;
    this.ui.selectGender(gender, first);
    this.preview.show(first);
  }

  private handleOutfit(id: CharacterId): void {
    this.selectedOutfit = id;
    this.selectedGender = OUTFITS[id].gender;
    this.ui.selectGender(this.selectedGender, id);
    this.ui.updatePreviewCaption(id);
    this.preview.show(id);
  }

  private handleConfirm(): void {
    this.preview.setActive(false);
    this.ui.fadeToBlack(() => {
      this.startNewGame();
      this.ui.fadeFromBlack();
    });
  }

  private handleContinue(): void {
    const save = this.save;
    if (!save) return;
    const id = isCharacterId(save.characterId) ? save.characterId : 'male_1';
    this.ui.fadeToBlack(() => {
      this.enterGame(id, {
        x: save.position.x,
        z: save.position.z,
        day: save.day,
        minutes: save.time,
        activities: save.activities,
      });
      this.ui.fadeFromBlack();
    });
  }

  private startNewGame(): void {
    const minutes = localStartMinutes(this.settings.realTimeStart);
    this.titleMinutes = minutes;
    this.activities = {};
    this.lateNotified = false;
    this.enterGame(this.selectedOutfit, null, minutes);
  }

  private enterGame(
    outfit: CharacterId,
    saved: { x: number; z: number; day: number; minutes: number; activities: Record<string, boolean> } | null,
    freshMinutes?: number,
  ): void {
    if (!this.town) return;
    if (this.player) {
      this.player.character.dispose();
      this.player = null;
    }

    const spawn = this.town.layout.spawn;
    let spawnX = saved?.x ?? spawn.x;
    let spawnZ = saved?.z ?? spawn.z;
    // A save written before the map change may now sit inside a building or
    // beyond the new boundary. Fall back to the authored spawn point.
    if (saved) {
      const ground = this.town.collision.groundAt(spawnX, spawnZ, Number.POSITIVE_INFINITY);
      const safe = this.town.collision.resolve(spawnX, spawnZ, 0.34, ground);
      if (Math.hypot(safe.x - spawnX, safe.z - spawnZ) > 0.05) {
        spawnX = spawn.x;
        spawnZ = spawn.z;
      }
    }

    const character = this.library.create(outfit, this.curve);
    this.context.scene.add(character.container);
    this.player = new Player(character, this.town.collision, {
      x: spawnX,
      z: spawnZ,
    });
    this.player.yaw = 0;

    this.selectedOutfit = outfit;
    this.selectedGender = OUTFITS[outfit].gender;
    this.activities = saved ? { ...saved.activities } : {};
    this.clock = new GameClock(saved?.minutes ?? freshMinutes ?? this.titleMinutes, saved?.day ?? 1);
    this.lateNotified = this.clock.isLate;
    this.cafe?.reset(this.clock.day, this.clock.minutes);

    this.rig.reset(0);
    this.rig.update(0.016, this.player.position, { x: 0, y: 0 }, true);

    this.ui.showGame();
    this.ui.hidePrompt();
    this.ui.setJournalOpen(false);
    this.state = 'playing';
    this.nearby = null;
    this.promptKey = null;
    this.updateHud(true);
    this.lastFrame = performance.now();
    void this.audio.start();
    this.audio.setVolume(this.settings.volume);
  }

  private openPause(): void {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.ui.openSettings(true);
    this.ui.hidePrompt();
    this.player?.velocity.set(0, 0, 0);
  }

  private handleOpenSettings(fromGame: boolean): void {
    if (fromGame) this.openPause();
    else this.ui.openSettings(false);
  }

  private handleCloseSettings(): void {
    this.ui.closeSettings();
    if (this.state === 'paused') {
      this.state = 'playing';
      this.lastFrame = performance.now();
    }
  }

  private handleLanguage(locale: Locale): void {
    if (locale !== 'id' && locale !== 'en') return;
    this.settings.language = locale;
    saveSettings(this.settings);
    void setLocale(locale).then(() => {
      this.ui.setLocale(locale);
      this.updateHud(true);
    });
  }

  private handleQuality(quality: Quality): void {
    this.settings.quality = quality;
    saveSettings(this.settings);
    applyQuality(this.context.renderer, this.context.sun, quality);
  }

  private handleCurve(value: number): void {
    this.settings.curve = value;
    saveSettings(this.settings);
    setCurveStrength(this.curve, value);
  }

  private handleRealTimeStart(enabled: boolean): void {
    this.settings.realTimeStart = enabled;
    saveSettings(this.settings);
    if (this.state === 'title' || this.state === 'select') {
      this.titleMinutes = localStartMinutes(enabled);
      this.ui.showLocalTime(this.titleMinutes);
    }
  }

  private handleSensitivity(value: number): void {
    this.settings.sensitivity = value;
    saveSettings(this.settings);
    this.rig.sensitivity = value;
  }

  private handleVolume(value: number): void {
    this.settings.volume = value;
    saveSettings(this.settings);
    this.audio.setVolume(value);
  }

  private handleReset(): void {
    if (!window.confirm(t('settings.resetConfirm'))) return;
    // The unload handler writes the live state back to storage. Stop it from
    // resurrecting the save we are about to delete.
    this.resetting = true;
    clearSave();
    window.location.reload();
  }

  private persist(): void {
    if (this.resetting) return;
    if (!this.player) return;
    const data = createSave(
      this.selectedOutfit,
      this.clock.day,
      this.clock.minutes,
      this.activities,
      { x: this.player.position.x, z: this.player.position.z },
    );
    writeSave(data);
    this.save = loadSave();
  }
}
