import { phaseForMinutes, type DayPhase } from './clock';

/**
 * Time-of-day greeting used by the speech bubbles. Keeping the mapping in one
 * pure function means the morning/noon/evening/night wording can be tested
 * without a DOM or a running clock.
 */
export function greetingKeyForPhase(phase: DayPhase): string {
  return `greeting.${phase}`;
}

export function greetingKeyForMinutes(minutes: number): string {
  return greetingKeyForPhase(phaseForMinutes(minutes));
}
