import * as THREE from 'three';
import { clamp, smoothstep } from '../core/math';
import { wrapMinutes } from '../gameplay/clock';

/** The sun crosses the horizon shortly before the town wakes up. */
export const SUNRISE_MINUTES = 5 * 60 + 50;
export const SUNSET_MINUTES = 18 * 60 + 10;
/** At its highest the sun sits low enough to keep long, readable shadows. */
export const MAX_SUN_ELEVATION = THREE.MathUtils.degToRad(63);

interface Keyframe {
  minute: number;
  top: number;
  horizon: number;
  ground: number;
  fog: number;
  hemiIntensity: number;
  glow: number;
  exposure: number;
}

/**
 * The sky is anchored to sunrise and sunset rather than to a fixed morning
 * hour. Between these keys the palette moves continuously, so a game started
 * at 03:00 or 21:00 still reads as the same world at a different hour.
 */
const KEYFRAMES: Keyframe[] = [
  { minute: 0, top: 0x0a1424, horizon: 0x1a2636, ground: 0x111a1f, fog: 0x18232f, hemiIntensity: 0.28, glow: 0.95, exposure: 1.04 },
  { minute: 270, top: 0x101c2e, horizon: 0x2a3142, ground: 0x171c20, fog: 0x222b38, hemiIntensity: 0.32, glow: 0.92, exposure: 1.03 },
  { minute: 330, top: 0x2b3b55, horizon: 0x8e6a63, ground: 0x2b2c2c, fog: 0x54505a, hemiIntensity: 0.5, glow: 0.8, exposure: 1.02 },
  { minute: 350, top: 0x435a78, horizon: 0xd58a5f, ground: 0x3a3833, fog: 0x8a7368, hemiIntensity: 0.65, glow: 0.62, exposure: 1.02 },
  { minute: 390, top: 0x6a90b4, horizon: 0xf0c79a, ground: 0x5f6050, fog: 0xc4b39f, hemiIntensity: 0.95, glow: 0.3, exposure: 1.03 },
  { minute: 540, top: 0x5a8dbb, horizon: 0xdce9ea, ground: 0x6d725c, fog: 0xcdd8d7, hemiIntensity: 1.12, glow: 0.08, exposure: 1.02 },
  { minute: 720, top: 0x4f86b8, horizon: 0xdfeaec, ground: 0x70745f, fog: 0xcdd9da, hemiIntensity: 1.2, glow: 0.0, exposure: 1.0 },
  { minute: 1020, top: 0x6c9bc2, horizon: 0xe9e0cd, ground: 0x6a6555, fog: 0xcfcfc2, hemiIntensity: 1.05, glow: 0.1, exposure: 1.01 },
  { minute: 1090, top: 0x7c93ad, horizon: 0xf0b077, ground: 0x4f4c42, fog: 0xb9a189, hemiIntensity: 0.85, glow: 0.55, exposure: 1.03 },
  { minute: 1125, top: 0x4b5a72, horizon: 0xc47b58, ground: 0x33352f, fog: 0x6f6260, hemiIntensity: 0.6, glow: 0.85, exposure: 1.04 },
  { minute: 1230, top: 0x1c2a3d, horizon: 0x3b3a4a, ground: 0x1b2228, fog: 0x2b3442, hemiIntensity: 0.36, glow: 1.0, exposure: 1.05 },
  { minute: 1440, top: 0x0a1424, horizon: 0x1a2636, ground: 0x111a1f, fog: 0x18232f, hemiIntensity: 0.28, glow: 0.95, exposure: 1.04 },
];

export interface TimePalette {
  top: THREE.Color;
  horizon: THREE.Color;
  ground: THREE.Color;
  fog: THREE.Color;
  sun: THREE.Color;
  sunIntensity: number;
  sunElevation: number;
  hemiIntensity: number;
  glow: number;
  exposure: number;
  night: number;
}

const colorCache = new Map<number, THREE.Color>();
function color(hex: number): THREE.Color {
  let value = colorCache.get(hex);
  if (!value) {
    value = new THREE.Color(hex);
    colorCache.set(hex, value);
  }
  return value;
}

/** Solar phase in radians: 0 at sunrise, pi/2 at noon, pi at sunset. */
function solarPhase(minutes: number): number {
  const time = wrapMinutes(minutes);
  return ((time - SUNRISE_MINUTES) / (SUNSET_MINUTES - SUNRISE_MINUTES)) * Math.PI;
}

/** Sun height above the horizon in radians. Negative at night. */
export function sunElevationAt(minutes: number): number {
  return MAX_SUN_ELEVATION * Math.sin(solarPhase(minutes));
}

/**
 * Direction from the town toward the sun. East at sunrise, south at noon,
 * west at sunset, then below the horizon through the night.
 */
export function sunDirectionAt(minutes: number, target = new THREE.Vector3()): THREE.Vector3 {
  const phase = solarPhase(minutes);
  const elevation = MAX_SUN_ELEVATION * Math.sin(phase);
  const horizontal = Math.cos(elevation);
  return target
    .set(Math.cos(phase) * horizontal, Math.sin(elevation), Math.sin(phase) * horizontal)
    .normalize();
}

interface ColorStop {
  degrees: number;
  hex: number;
}

// Warm at the horizon, increasingly neutral as the air mass above the town
// thins. The values are deliberately restrained: no orange at noon.
const SUN_STOPS: ColorStop[] = [
  { degrees: -2, hex: 0xff5424 },
  { degrees: 1, hex: 0xff7a3a },
  { degrees: 6, hex: 0xffa25c },
  { degrees: 12, hex: 0xffc98a },
  { degrees: 22, hex: 0xffe0b4 },
  { degrees: 40, hex: 0xfff3e0 },
  { degrees: 65, hex: 0xfffaf0 },
];

/** Sunlight colour from elevation. Below the horizon it fades to a cold glow. */
export function sunColorAt(elevationRadians: number, target = new THREE.Color()): THREE.Color {
  const degrees = THREE.MathUtils.radToDeg(elevationRadians);
  if (degrees <= SUN_STOPS[0].degrees) return target.copy(color(SUN_STOPS[0].hex));
  for (let i = 1; i < SUN_STOPS.length; i += 1) {
    const to = SUN_STOPS[i];
    if (degrees <= to.degrees) {
      const from = SUN_STOPS[i - 1];
      const span = to.degrees - from.degrees || 1;
      const t = smoothstep(0, 1, (degrees - from.degrees) / span);
      return target.copy(color(from.hex)).lerp(color(to.hex), t);
    }
  }
  return target.copy(color(SUN_STOPS[SUN_STOPS.length - 1].hex));
}

/**
 * Directional light strength from elevation. Zero below the horizon, a soft
 * ramp through sunrise, and a plateau that is slightly stronger at noon.
 */
export function sunIntensityAt(elevationRadians: number): number {
  const degrees = THREE.MathUtils.radToDeg(elevationRadians);
  if (degrees <= -1) return 0;
  const rise = smoothstep(-1, 6, degrees);
  const altitude = 0.7 + 0.3 * smoothstep(6, 55, degrees);
  return 2.6 * rise * altitude;
}

export function paletteAt(minutes: number): TimePalette {
  const time = wrapMinutes(minutes);

  let from = KEYFRAMES[0];
  let to = KEYFRAMES[KEYFRAMES.length - 1];
  for (let i = 0; i < KEYFRAMES.length - 1; i += 1) {
    if (time >= KEYFRAMES[i].minute && time <= KEYFRAMES[i + 1].minute) {
      from = KEYFRAMES[i];
      to = KEYFRAMES[i + 1];
      break;
    }
  }

  const span = to.minute - from.minute || 1;
  const t = smoothstep(0, 1, (time - from.minute) / span);
  const mix = (a: number, b: number): THREE.Color => color(a).clone().lerp(color(b), t);
  const number = (a: number, b: number): number => a + (b - a) * t;

  const sunElevation = sunElevationAt(time);
  const degrees = THREE.MathUtils.radToDeg(sunElevation);
  const night = 1 - smoothstep(-8, 0, degrees);

  return {
    top: mix(from.top, to.top),
    horizon: mix(from.horizon, to.horizon),
    ground: mix(from.ground, to.ground),
    fog: mix(from.fog, to.fog),
    sun: sunColorAt(sunElevation),
    sunIntensity: sunIntensityAt(sunElevation),
    sunElevation,
    hemiIntensity: number(from.hemiIntensity, to.hemiIntensity),
    glow: number(from.glow, to.glow),
    exposure: number(from.exposure, to.exposure),
    night: clamp(night, 0, 1),
  };
}

export class Sky {
  readonly mesh: THREE.Mesh;
  private readonly material: THREE.ShaderMaterial;

  constructor() {
    this.material = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      depthTest: false,
      fog: false,
      uniforms: {
        uTop: { value: new THREE.Color(0x8fa9bd) },
        uHorizon: { value: new THREE.Color(0xe0d4c2) },
        uGround: { value: new THREE.Color(0x5b5d51) },
        uSunColor: { value: new THREE.Color(0xffd7a4) },
        uSunDirection: { value: new THREE.Vector3(0.3, 0.6, -0.5).normalize() },
        uNight: { value: 0 },
      },
      vertexShader: /* glsl */ `
        varying vec3 vDirection;
        void main() {
          vDirection = normalize( position );
          gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 uTop;
        uniform vec3 uHorizon;
        uniform vec3 uGround;
        uniform vec3 uSunColor;
        uniform vec3 uSunDirection;
        uniform float uNight;
        varying vec3 vDirection;

        float hash( vec2 p ) {
          return fract( sin( dot( p, vec2( 127.1, 311.7 ) ) ) * 43758.5453 );
        }

        float noise( vec2 p ) {
          vec2 i = floor( p );
          vec2 f = fract( p );
          f = f * f * ( 3.0 - 2.0 * f );
          return mix(
            mix( hash( i ), hash( i + vec2( 1.0, 0.0 ) ), f.x ),
            mix( hash( i + vec2( 0.0, 1.0 ) ), hash( i + vec2( 1.0, 1.0 ) ), f.x ),
            f.y
          );
        }

        float fbm( vec2 p ) {
          float value = 0.0;
          float amplitude = 0.5;
          for ( int i = 0; i < 4; i += 1 ) {
            value += noise( p ) * amplitude;
            p = p * 2.03 + 11.7;
            amplitude *= 0.5;
          }
          return value;
        }

        void main() {
          vec3 direction = normalize( vDirection );
          vec3 sunDir = normalize( uSunDirection );
          float height = direction.y;
          float skyMix = smoothstep( -0.03, 0.42, height );

          // The horizon leans warm toward the sun, especially when it is low.
          vec2 horizontal = normalize( vec2( direction.x, direction.z ) + vec2( 1e-5 ) );
          vec2 sunHorizontal = normalize( vec2( sunDir.x, sunDir.z ) + vec2( 1e-5 ) );
          float sunSide = max( dot( horizontal, sunHorizontal ), 0.0 );
          float lowSun = 1.0 - smoothstep( 0.0, 0.5, max( sunDir.y, 0.0 ) );
          // The warmth only belongs to the sun near the horizon. Without this
          // gate the red sunset colour tints the whole night sky.
          lowSun *= smoothstep( -0.22, 0.05, sunDir.y );
          vec3 horizon = mix( uHorizon, uSunColor, lowSun * ( 0.25 + 0.45 * pow( sunSide, 2.0 ) ) );

          vec3 sky = mix( horizon, uTop, skyMix );
          sky = mix( uGround, sky, smoothstep( -0.24, 0.01, height ) );

          // Atmospheric glow follows the sun even after it dips below the rim.
          float sunDot = max( dot( direction, sunDir ), 0.0 );
          float glow = smoothstep( -0.18, 0.04, sunDir.y );
          float halo = pow( sunDot, 6.0 ) * ( 0.1 + lowSun * 0.3 ) * glow;
          halo += pow( sunDot, 2.0 ) * lowSun * 0.06 * glow;

          // A real disc with a soft limb, roughly half a degree across.
          float sunAngle = acos( clamp( dot( direction, sunDir ), -1.0, 1.0 ) );
          float discVisible = smoothstep( -0.02, 0.008, sunDir.y );
          float disc = ( 1.0 - smoothstep( 0.006, 0.011, sunAngle ) ) * discVisible;
          float core = ( 1.0 - smoothstep( 0.0, 0.007, sunAngle ) ) * discVisible;
          // A near-white core keeps the disc readable against the warm horizon.
          vec3 discColor = mix( uSunColor, vec3( 1.0 ), 0.7 );
          sky += uSunColor * halo;
          sky += discColor * ( disc * 2.4 + core * 1.5 );

          // Clouds catch the same light as the horizon.
          vec2 cloudUv = direction.xz / max( height + 0.12, 0.04 );
          float cloudNoise = fbm( cloudUv * 0.55 + vec2( 3.1, 8.4 ) );
          float cloud = smoothstep( 0.54, 0.78, cloudNoise ) * smoothstep( 0.0, 0.16, height );
          cloud *= 0.5 + 0.5 * smoothstep( -0.2, 0.35, height );
          vec3 cloudColor = mix( horizon, vec3( 1.0 ), 0.5 ) + uSunColor * halo * 1.4;
          cloudColor = mix( cloudColor, cloudColor * 0.24, uNight );
          sky = mix( sky, cloudColor, cloud * 0.55 );

          // Sparse stars, only above the horizon and only after dusk.
          vec2 starUv = vec2( atan( direction.z, direction.x ), asin( clamp( direction.y, -1.0, 1.0 ) ) ) * 24.0;
          vec2 starCell = floor( starUv );
          vec2 starFract = fract( starUv ) - 0.5;
          float star = step( 0.988, hash( starCell ) ) * ( 1.0 - smoothstep( 0.0, 0.16, length( starFract ) ) );
          star *= uNight * smoothstep( 0.03, 0.22, height );
          sky += vec3( 0.82, 0.88, 1.0 ) * star * 0.65;

          // Pale moon opposite the sun, so the night has a direction.
          vec3 moonDir = -sunDir;
          float moonAngle = acos( clamp( dot( direction, moonDir ), -1.0, 1.0 ) );
          float moonVisible = smoothstep( 0.0, 0.1, moonDir.y ) * uNight;
          float moonDisc = ( 1.0 - smoothstep( 0.009, 0.014, moonAngle ) ) * moonVisible;
          float moonHalo = pow( max( dot( direction, moonDir ), 0.0 ), 20.0 ) * 0.1 * moonVisible;
          sky += vec3( 0.8, 0.85, 0.94 ) * ( moonDisc * 0.85 + moonHalo );

          gl_FragColor = vec4( sky, 1.0 );
        }
      `,
    });

    const geometry = new THREE.SphereGeometry(320, 32, 20);
    this.mesh = new THREE.Mesh(geometry, this.material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = -10;
    this.mesh.name = 'SkyDome';
  }

  update(camera: THREE.Camera, palette: TimePalette, sunDirection: THREE.Vector3): void {
    this.mesh.position.copy(camera.position);
    this.material.uniforms.uTop.value.copy(palette.top);
    this.material.uniforms.uHorizon.value.copy(palette.horizon);
    this.material.uniforms.uGround.value.copy(palette.ground);
    this.material.uniforms.uSunColor.value.copy(palette.sun);
    this.material.uniforms.uSunDirection.value.copy(sunDirection);
    this.material.uniforms.uNight.value = palette.night;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.material.dispose();
  }
}
