import * as THREE from 'three';
import { clamp, damp, dampAngle } from '../core/math';

export class CameraRig {
  yaw = 0;
  pitch = 0.22;
  distance = 4.6;
  sensitivity = 1;

  private readonly target = new THREE.Vector3();
  private readonly desired = new THREE.Vector3();
  private readonly lookAt = new THREE.Vector3();
  private cinematicAngle = 0.6;
  private obstruction: ((from: THREE.Vector3, to: THREE.Vector3) => number) | null = null;
  /** Distance from the head target to the camera after obstruction handling. */
  clearance = 4.6;
  /** Height above the feet that the camera aims at; lowered while lying down. */
  targetHeight = 1.42;
  private goalHeight = 1.42;
  /**
   * Optional orbit angle the camera eases toward, used when a pose needs a
   * particular view, such as the side view of a sunbather. Any manual look
   * input cancels it so the player is never fought for control.
   */
  private orbitGoal: number | null = null;

  constructor(readonly camera: THREE.PerspectiveCamera) {}

  /** Supply a function returning the free fraction of a camera segment. */
  setObstructionResolver(resolve: (from: THREE.Vector3, to: THREE.Vector3) => number): void {
    this.obstruction = resolve;
  }

  reset(yaw = 0): void {
    this.yaw = yaw;
    this.pitch = 0.22;
    this.targetHeight = 1.42;
    this.goalHeight = 1.42;
    this.orbitGoal = null;
  }

  update(dt: number, focus: THREE.Vector3, look: { x: number; y: number }, snap = false): void {
    // Ease toward a suggested angle until the player takes over the orbit.
    if (Math.abs(look.x) > 0.0001) this.orbitGoal = null;
    this.yaw -= look.x * 0.0026 * this.sensitivity;
    if (this.orbitGoal !== null && !snap) {
      this.yaw = dampAngle(this.yaw, this.orbitGoal, 4.5, dt);
    }
    this.pitch = clamp(this.pitch + look.y * 0.0018 * this.sensitivity, -0.22, 0.92);
    this.targetHeight = damp(this.targetHeight, this.goalHeight, 6, dt);
    this.computeDesired(focus);

    if (snap) {
      this.camera.position.copy(this.desired);
    } else {
      this.camera.position.x = damp(this.camera.position.x, this.desired.x, 12, dt);
      this.camera.position.y = damp(this.camera.position.y, this.desired.y, 10, dt);
      this.camera.position.z = damp(this.camera.position.z, this.desired.z, 12, dt);
    }

    this.applyLookAt();
  }

  /** Aim at a new height without moving the orbit, e.g. when lying down. */
  setTargetHeight(height: number): void {
    this.goalHeight = height;
  }

  /** Ease the orbit toward an angle that frames the current pose. */
  orbitTo(yaw: number): void {
    this.orbitGoal = yaw;
  }

  /** Give the orbit back to the player without moving it. */
  releaseOrbit(): void {
    this.orbitGoal = null;
  }

  /** Jump the camera to the player after a map wrap; look angles stay intact. */
  snap(focus: THREE.Vector3): void {
    this.targetHeight = this.goalHeight;
    this.computeDesired(focus);
    this.camera.position.copy(this.desired);
    this.applyLookAt();
  }

  private computeDesired(focus: THREE.Vector3): void {
    this.target.set(focus.x, focus.y + this.targetHeight, focus.z);

    const horizontal = Math.cos(this.pitch) * this.distance;
    this.desired.set(
      this.target.x + Math.sin(this.yaw) * horizontal,
      this.target.y + Math.sin(this.pitch) * this.distance,
      this.target.z + Math.cos(this.yaw) * horizontal,
    );

    if (this.obstruction) {
      const free = this.obstruction(this.target, this.desired);
      if (free < 1) {
        // Keep a short over-the-shoulder distance rather than snapping into
        // the character's head when a wall is very close.
        this.desired.lerpVectors(this.target, this.desired, Math.max(0.16, free * 0.94));
      }
    }
    this.clearance = this.desired.distanceTo(this.target);
  }

  private applyLookAt(): void {
    this.lookAt.set(this.target.x, this.target.y + 0.06, this.target.z);
    this.camera.lookAt(this.lookAt);
  }

  /** Slow drift over the town, used behind the title and character screens. */
  updateCinematic(dt: number, focus = new THREE.Vector3(-4.5, 7.8, 0)): void {
    this.cinematicAngle += dt * 0.022;
    const radius = 37;
    const height = 16.5 + Math.sin(this.cinematicAngle * 0.6) * 1.4;
    this.camera.position.set(
      focus.x + Math.sin(this.cinematicAngle) * radius,
      height,
      focus.z + Math.cos(this.cinematicAngle) * radius,
    );
    this.camera.lookAt(focus);
  }

  /** Horizontal forward direction of the view, flattened to the ground plane. */
  forward(target = new THREE.Vector3()): THREE.Vector3 {
    return target.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
  }

  right(target = new THREE.Vector3()): THREE.Vector3 {
    return target.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }
}
