import * as THREE from 'three';
import { mulberry32 } from '../core/math';

const cache = new Map<string, THREE.Texture>();

function createCanvas(size: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  return canvas;
}

function finish(canvas: HTMLCanvasElement, repeat = 1): THREE.CanvasTexture {
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(repeat, repeat);
  texture.anisotropy = 4;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}

/** Soft, nearly monochrome grain. Tinted by the material colour at runtime. */
function grainTexture(
  key: string,
  size: number,
  base: number,
  contrast: number,
  detail: (ctx: CanvasRenderingContext2D, random: () => number) => void = () => {},
): THREE.Texture {
  const cached = cache.get(key);
  if (cached) return cached;

  const canvas = createCanvas(size);
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is unavailable');

  const random = mulberry32(0x51f15e + size);
  const image = ctx.createImageData(size, size);
  for (let i = 0; i < image.data.length; i += 4) {
    const value = Math.round(base + (random() - 0.5) * contrast);
    image.data[i] = value;
    image.data[i + 1] = value;
    image.data[i + 2] = value;
    image.data[i + 3] = 255;
  }
  ctx.putImageData(image, 0, 0);
  detail(ctx, random);

  const texture = finish(canvas);
  cache.set(key, texture);
  return texture;
}

export function stoneTexture(): THREE.Texture {
  return grainTexture('stone', 256, 218, 30, (ctx, random) => {
    // Ashlar: long, staggered blocks with thin mortar joints.
    const rowHeight = 30;
    for (let row = 0; row < 9; row += 1) {
      const y = row * rowHeight;
      let x = row % 2 === 0 ? -18 : -42;
      while (x < 256) {
        const width = 38 + Math.floor(random() * 30);
        ctx.strokeStyle = 'rgba(72, 68, 62, 0.34)';
        ctx.lineWidth = 1.6;
        ctx.strokeRect(x + 1.5, y + 1.5, width - 3, rowHeight - 3);
        const shade = 0.02 + random() * 0.055;
        ctx.fillStyle = `rgba(62, 58, 52, ${shade})`;
        ctx.fillRect(x + 2, y + 2, width - 4, rowHeight - 4);
        x += width;
      }
    }
    for (let i = 0; i < 70; i += 1) {
      ctx.fillStyle = `rgba(58, 54, 48, ${0.02 + random() * 0.05})`;
      ctx.beginPath();
      ctx.arc(random() * 256, random() * 256, 2 + random() * 13, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

/** Smaller, irregular paving stones. Kept separate from the wall texture so
 * streets do not read as a repeating brick grid under the player's feet. */
export function cobbleTexture(): THREE.Texture {
  return grainTexture('cobble', 256, 214, 26, (ctx, random) => {
    for (let row = 0; row < 14; row += 1) {
      const y = row * 19 + (row % 2) * 2;
      let x = -8 - random() * 22;
      while (x < 256) {
        const width = 15 + Math.floor(random() * 18);
        const height = 15 + Math.floor(random() * 5);
        const inset = 1.4;
        ctx.fillStyle = `rgba(70, 66, 58, ${0.06 + random() * 0.07})`;
        ctx.beginPath();
        ctx.roundRect(x + inset, y + inset, width - inset * 2, height - inset * 2, 4);
        ctx.fill();
        ctx.strokeStyle = 'rgba(62, 58, 52, 0.26)';
        ctx.lineWidth = 1.1;
        ctx.stroke();
        x += width + 1.5;
      }
    }
    // Small grit and wear patches.
    for (let i = 0; i < 160; i += 1) {
      const value = random() > 0.5 ? 255 : 40;
      ctx.fillStyle = `rgba(${value}, ${value}, ${value - 10}, ${0.02 + random() * 0.035})`;
      ctx.beginPath();
      ctx.arc(random() * 256, random() * 256, 0.6 + random() * 1.8, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

export function plasterTexture(): THREE.Texture {
  return grainTexture('plaster', 128, 226, 22, (ctx, random) => {
    for (let i = 0; i < 60; i += 1) {
      ctx.fillStyle = `rgba(120, 112, 98, ${0.02 + random() * 0.04})`;
      ctx.fillRect(random() * 128, random() * 128, 8 + random() * 26, 4 + random() * 18);
    }
  });
}

export function roofTexture(): THREE.Texture {
  return grainTexture('roof', 256, 206, 30, (ctx, random) => {
    for (let row = 0; row < 8; row += 1) {
      const y = row * 32;
      ctx.fillStyle = 'rgba(52, 36, 30, 0.22)';
      ctx.fillRect(0, y + 27, 256, 4);
      for (let col = 0; col < 8; col += 1) {
        const shade = 0.02 + random() * 0.09;
        ctx.fillStyle = `rgba(40, 26, 22, ${shade})`;
        ctx.fillRect(col * 32 + (row % 2) * 16, y, 1.5, 30);
      }
    }
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1;
    for (let row = 0; row < 8; row += 1) {
      ctx.beginPath();
      ctx.moveTo(0, row * 32 + 2);
      ctx.lineTo(256, row * 32 + 2);
      ctx.stroke();
    }
  });
}

export function woodTexture(): THREE.Texture {
  return grainTexture('wood', 128, 200, 34, (ctx, random) => {
    for (let i = 0; i < 22; i += 1) {
      const x = random() * 128;
      ctx.strokeStyle = `rgba(40, 26, 18, ${0.06 + random() * 0.12})`;
      ctx.lineWidth = 0.6 + random() * 1.4;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.bezierCurveTo(x + random() * 4 - 2, 40, x + random() * 6 - 3, 90, x + random() * 4 - 2, 128);
      ctx.stroke();
    }
  });
}

export function grassTexture(): THREE.Texture {
  return grainTexture('grass', 128, 202, 52, (ctx, random) => {
    for (let i = 0; i < 500; i += 1) {
      const shade = random() > 0.5 ? 0.08 : 0.14;
      ctx.strokeStyle = `rgba(30, 54, 22, ${shade})`;
      ctx.lineWidth = 0.8;
      const x = random() * 128;
      const y = random() * 128;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + random() * 2 - 1, y - 2 - random() * 4);
      ctx.stroke();
    }
  });
}

export function fabricTexture(): THREE.Texture {
  return grainTexture('fabric', 64, 230, 16, (ctx) => {
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.05)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 64; i += 4) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i, 64);
      ctx.moveTo(0, i);
      ctx.lineTo(64, i);
      ctx.stroke();
    }
  });
}

/** Fine beach grit with faint wind ripples. */
export function sandTexture(): THREE.Texture {
  return grainTexture('sand', 256, 224, 34, (ctx, random) => {
    for (let i = 0; i < 900; i += 1) {
      const dark = random() > 0.5;
      ctx.fillStyle = dark
        ? `rgba(104, 92, 70, ${0.04 + random() * 0.08})`
        : `rgba(255, 250, 232, ${0.05 + random() * 0.08})`;
      ctx.beginPath();
      ctx.arc(random() * 256, random() * 256, 0.5 + random() * 1.6, 0, Math.PI * 2);
      ctx.fill();
    }
    // Shallow wind ripples, kept almost horizontal so they read underfoot.
    for (let row = 0; row < 26; row += 1) {
      const y = row * 10 + random() * 4;
      ctx.strokeStyle = `rgba(96, 84, 64, ${0.03 + random() * 0.04})`;
      ctx.lineWidth = 0.8 + random() * 1.2;
      ctx.beginPath();
      ctx.moveTo(0, y);
      for (let x = 0; x <= 256; x += 16) {
        ctx.lineTo(x, y + Math.sin(x * 0.06 + row) * 1.6);
      }
      ctx.stroke();
    }
  });
}

/** Ringed, fibrous palm trunk. */
export function palmBarkTexture(): THREE.Texture {
  return grainTexture('palm-bark', 128, 196, 26, (ctx, random) => {
    for (let y = 0; y < 128; y += 5) {
      ctx.fillStyle = `rgba(46, 34, 22, ${0.09 + random() * 0.08})`;
      ctx.fillRect(0, y + random() * 1.5, 128, 1.1 + random() * 0.8);
      ctx.fillStyle = `rgba(255, 226, 184, ${0.02 + random() * 0.04})`;
      ctx.fillRect(0, y + 2.4, 128, 0.8);
    }
    for (let i = 0; i < 40; i += 1) {
      ctx.fillStyle = `rgba(38, 28, 18, ${0.03 + random() * 0.05})`;
      ctx.fillRect(random() * 128, random() * 128, 1, 4 + random() * 10);
    }
  });
}

/** Broad, soft reflections. Tinted by the water material colour. */
export function seaTexture(): THREE.Texture {
  return grainTexture('sea', 256, 208, 18, (ctx, random) => {
    for (let i = 0; i < 70; i += 1) {
      const y = random() * 256;
      const width = 24 + random() * 90;
      const x = random() * 256;
      ctx.strokeStyle = `rgba(238, 252, 252, ${0.04 + random() * 0.1})`;
      ctx.lineWidth = 0.8 + random() * 2.2;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.bezierCurveTo(x + width * 0.3, y - 2, x + width * 0.7, y + 2, x + width, y);
      ctx.stroke();
    }
    for (let i = 0; i < 90; i += 1) {
      ctx.fillStyle = `rgba(12, 40, 48, ${0.04 + random() * 0.08})`;
      ctx.beginPath();
      ctx.ellipse(random() * 256, random() * 256, 3 + random() * 14, 1 + random() * 3, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

/** Lacy foam for the shoreline strips. */
export function foamTexture(): THREE.Texture {
  return grainTexture('foam', 128, 236, 28, (ctx, random) => {
    for (let i = 0; i < 260; i += 1) {
      ctx.fillStyle = random() > 0.35
        ? `rgba(255, 255, 255, ${0.1 + random() * 0.25})`
        : `rgba(178, 200, 198, ${0.08 + random() * 0.12})`;
      ctx.beginPath();
      ctx.arc(random() * 128, random() * 128, 1 + random() * 5, 0, Math.PI * 2);
      ctx.fill();
    }
    for (let i = 0; i < 40; i += 1) {
      ctx.strokeStyle = `rgba(255, 255, 255, ${0.12 + random() * 0.2})`;
      ctx.lineWidth = 0.8 + random();
      ctx.beginPath();
      ctx.arc(random() * 128, random() * 128, 3 + random() * 14, 0, Math.PI * 2);
      ctx.stroke();
    }
  });
}

export function disposeTextures(): void {
  for (const texture of cache.values()) texture.dispose();
  cache.clear();
}

/**
 * Canvas signage is painted before the DOM may have requested the webfonts.
 * Load both families first so the first town build bakes the real type.
 */
export async function prepareSignFonts(): Promise<void> {
  if (typeof document === 'undefined' || !document.fonts) return;
  try {
    await Promise.all([
      document.fonts.load('500 105px "Fraunces Variable"'),
      document.fonts.load('600 58px "Inter Variable"'),
    ]);
    await document.fonts.ready;
  } catch {
    // The CSS fallbacks still produce readable signage.
  }
}

/** A one-off, clamped canvas texture for painted signage. */
function labelTexture(
  key: string,
  width: number,
  height: number,
  draw: (ctx: CanvasRenderingContext2D) => void,
): THREE.Texture {
  const cached = cache.get(key);
  if (cached) return cached;

  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is unavailable');
  draw(ctx);

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.anisotropy = 8;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  cache.set(key, texture);
  return texture;
}

/**
 * The container bar's name plate. Dark painted metal with warm cream type,
 * matching the reference's black shell and oak counter.
 */
export function cafeNameTexture(): THREE.Texture {
  return labelTexture('cafe-name', 1024, 168, (ctx) => {
    ctx.fillStyle = '#101412';
    ctx.fillRect(0, 0, 1024, 168);
    const gradient = ctx.createLinearGradient(0, 0, 0, 168);
    gradient.addColorStop(0, 'rgba(255, 246, 228, 0.06)');
    gradient.addColorStop(0.5, 'rgba(255, 246, 228, 0)');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0.22)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 1024, 168);
    ctx.strokeStyle = 'rgba(235, 221, 197, 0.38)';
    ctx.lineWidth = 5;
    ctx.strokeRect(13, 13, 998, 142);
    ctx.fillStyle = '#efe5d1';
    ctx.font = '500 105px "Fraunces Variable", "Iowan Old Style", Georgia, serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('TerrasKastil.', 512, 88);
  });
}

/** Chalk-style board with the same three drinks the popup menu offers. */
export function cafeMenuTexture(): THREE.Texture {
  return labelTexture('cafe-menu', 640, 672, (ctx) => {
    ctx.fillStyle = '#111513';
    ctx.fillRect(0, 0, 640, 672);
    ctx.strokeStyle = 'rgba(235, 221, 197, 0.42)';
    ctx.lineWidth = 4;
    ctx.strokeRect(18, 18, 604, 636);

    ctx.fillStyle = '#efe5d1';
    ctx.font = '600 58px "Inter Variable", "Avenir Next", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('MENU', 320, 112);
    ctx.font = '400 23px "Inter Variable", "Avenir Next", sans-serif';
    ctx.fillStyle = 'rgba(239, 229, 209, 0.62)';
    ctx.fillText('TERRASKASTIL.  ·  BUKA 24 JAM', 320, 152);

    ctx.strokeStyle = 'rgba(235, 221, 197, 0.28)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(58, 184);
    ctx.lineTo(582, 184);
    ctx.stroke();

    const rows = [
      ['Hot Latte', 'Gratis', 'Espresso · susu hangat · latte art'],
      ['Hot Matcha Latte', 'Gratis', 'Matcha · susu hangat · busa lembut'],
      ['Iced Matcha', 'Gratis', 'Matcha dingin · es · krim'],
    ];
    rows.forEach(([name, price, note], index) => {
      const top = 246 + index * 128;
      ctx.textAlign = 'left';
      ctx.fillStyle = '#f2e9d7';
      ctx.font = '600 34px "Inter Variable", "Avenir Next", sans-serif';
      ctx.fillText(name, 58, top);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#d9b483';
      ctx.font = '600 24px "Inter Variable", "Avenir Next", sans-serif';
      ctx.fillText(price, 582, top);
      ctx.textAlign = 'left';
      ctx.fillStyle = 'rgba(239, 229, 209, 0.56)';
      ctx.font = '400 20px "Inter Variable", "Avenir Next", sans-serif';
      ctx.fillText(note, 58, top + 32);
    });

    ctx.strokeStyle = 'rgba(235, 221, 197, 0.2)';
    ctx.beginPath();
    ctx.moveTo(58, 610);
    ctx.lineTo(582, 610);
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(239, 229, 209, 0.7)';
    ctx.font = '500 21px "Inter Variable", "Avenir Next", sans-serif';
    ctx.fillText('PAGI  ·  SIANG  ·  MALAM', 320, 638);
  });
}

