    gradient.addColorStop(1, '#242825');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 512, 104);
    ctx.strokeStyle = 'rgba(226, 232, 228, 0.4)';
    ctx.lineWidth = 3;
    ctx.strokeRect(5, 5, 502, 94);
